    /** 下次允许重新扫描节点的实体存活 tick；使用绝对 tick 避免激活切换导致少算或多算 */
    private long nextRetargetTick;
    /** 搜索半径平方；配置值小于等于 0 时为 0，表示禁用节点寻路 */
