package com.hilltopvillage.doc;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;

import org.bukkit.Bukkit;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * 运行时命令文档生成器（启动时异步写出 {@code commands.md}）。
 *
 * <p>维护义务：本类内容为硬编码文本，修正命令行为/文案时必须与 README 命令表、
 * {@code plugin.yml} usage 同步核对（fix5 M-18 教训：leave 击杀口径、start 前置、
 * 三命令的可选参数行曾与实现脱节）。</p>
 */
public class CommandsDocumentGenerator {

    private final JavaPlugin plugin;

    public CommandsDocumentGenerator(JavaPlugin plugin) {
        this.plugin = plugin;
    }

    public void generate() {
        File docFile = new File(plugin.getDataFolder(), "commands.md");
        StringBuilder md = new StringBuilder();

        md.append("# 村民守卫战PLUS — 命令文档

");
        md.append("> 本文档由插件在服务器启动时自动生成/更新。
");
        md.append("> 最后更新: ").append(new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss").format(new java.util.Date())).append("

");
        md.append("---

");

        md.append("## 基础命令

");

        md.append("### `/hilltop join`

");
        md.append("- **功能**: 加入游戏等待队列。
");
        md.append("- **权限**: 无（所有玩家可用）。
");
        md.append("- **参数**: `[竞技场]` — 可选，竞技场 ID（不填时自动选择可用竞技场）。
");
        md.append("- **使用示例**: `/hilltop join`
");
        md.append("- **注意事项**: 需在游戏状态为 WAITING 或 STARTING 时使用，游戏开始后无法加入。

");

        md.append("### `/hilltop leave`

");
        md.append("- **功能**: 退出游戏。
");
        md.append("- **权限**: 无（所有玩家可用）。
");
        md.append("- **参数**: 无。
");
        md.append("- **使用示例**: `/hilltop leave`
");
        md.append("- **注意事项**: 中途离开只累计击杀/阵亡/修复节点数与获取水晶，不计胜负（胜/负场与场次需要打到结算）。撤离后物品快照原样归还。

");

