    class Slots {

        @Test
        @DisplayName("槽位越界（>= gui.size）的条目被跳过")
        void slotBeyondGuiSizeIsSkipped() throws IOException {
            LogCapture logs = attachLogCapture(host.getLogger());
            ShopConfig config = load(singleItem("""
                    slot: 54
