    }

    @Test
    @DisplayName("第 8 步失败中止：先恢复第 5 步删掉的节点，再重新启用竞技场")
    void deploymentFailureRestoresNodesBeforeReinstate() throws Exception {
        File nodesFile = dataFolder.resolve("nodes.yml").toFile();
        TestPaths.write(nodesFile, """
                nodes:
                  - world: hilltop_arena1
                    x: 10
                    y: 64
                    z: 10
                  - world: hilltop_arena1
                    x: 20
                    y: 64
                    z: 20
                  - world: lobby
                    x: 0
                    y: 64
                    z: 0
                """);

        World world = server.addSimpleWorld(WORLD);
        Location core = new Location(world, 10, 65, 10);
        ArenaDefinition definition = new ArenaDefinition(
                ARENA_ID, "Arena 1", true, WORLD, null, core, List.of(), 8, 10, 40, 0);
        when(definitions.getArena(ARENA_ID)).thenReturn(definition);

        ArenaInstance live = mock(ArenaInstance.class);
        when(live.getState()).thenReturn(GameState.WAITING);
        when(live.getNodeSystem()).thenReturn(mock(NodeSystem.class));
        when(multi.getArena(ARENA_ID)).thenReturn(live);
        when(mapRestore.getPendingCount(WORLD)).thenReturn(0);

        // 第 8 步：模拟 arenas.yml 不可写（重置前 core 仍在 → reinstate 会成功）
        when(definitions.clearDeploymentData(ARENA_ID)).thenReturn(false);
        when(multi.enableArena(ARENA_ID)).thenReturn(true);

        AtomicReference<Outcome> result = new AtomicReference<>();
        service.reset(ARENA_ID, result::set);

        Outcome outcome = result.get();
        assertNotNull(outcome, "中止路径必须回调一次");

        List<Location> restored = NodeSystem.readNodesForWorld(dataFolder.toFile(), WORLD);
        assertEquals(2, restored.size(),
                "第 8 步失败后必须把第 5 步删掉的 2 个节点恢复，否则重新启用的是 0 节点空图");
        assertEquals(10, restored.get(0).getBlockX());
        assertEquals(20, restored.get(1).getBlockX());
        assertEquals(1, NodeSystem.readNodesForWorld(dataFolder.toFile(), "lobby").size(),
                "回滚只能影响目标世界，不能动其它竞技场/大厅的节点");

        assertEquals("deployment", outcome.failStep());
        assertTrue(outcome.reinstated(), "core 未被清掉，中止应能恢复启用");
        assertFalse(outcome.nodesCleared(),
                "节点已随中止回滚，不能再报告 nodesCleared=true");
        verify(multi).enableArena(ARENA_ID);
    }

    @Test
    @DisplayName("节点回滚也失败：绝不重新启用，否则仍是 0 节点空图")
    void rollbackFailureKeepsArenaDisabled() throws Exception {
        File nodesFile = dataFolder.resolve("nodes.yml").toFile();
        TestPaths.write(nodesFile, """
                nodes:
                  - world: hilltop_arena1
                    x: 10
                    y: 64
                    z: 10
                  - world: hilltop_arena1
                    x: 20
                    y: 64
                    z: 20
                """);

        World world = server.addSimpleWorld(WORLD);
        Location core = new Location(world, 10, 65, 10);
        ArenaDefinition definition = new ArenaDefinition(
                ARENA_ID, "Arena 1", true, WORLD, null, core, List.of(), 8, 10, 40, 0);
        when(definitions.getArena(ARENA_ID)).thenReturn(definition);

        ArenaInstance live = mock(ArenaInstance.class);
        when(live.getState()).thenReturn(GameState.WAITING);
        when(live.getNodeSystem()).thenReturn(mock(NodeSystem.class));
        when(multi.getArena(ARENA_ID)).thenReturn(live);
        when(mapRestore.getPendingCount(WORLD)).thenReturn(0);

        Path moved = dataFolder.resolveSibling(dataFolder.getFileName() + "-moved");
        doAnswer(invocation -> {
            // 让 dataFolder 本身变成普通文件：随后 restoreNodesForWorld 无法创建 nodes.yml。
            Files.move(dataFolder, moved);
            Files.writeString(dataFolder, "not a directory");
            return false;
        }).when(definitions).clearDeploymentData(ARENA_ID);

        try {
            AtomicReference<Outcome> result = new AtomicReference<>();
            service.reset(ARENA_ID, result::set);

            Outcome outcome = result.get();
            assertNotNull(outcome);
            assertEquals("deployment", outcome.failStep());
            assertFalse(outcome.reinstated(), "节点补不回来时禁止重新启用");
            assertEquals(ReinstateSkip.NODE_ROLLBACK_FAILED, outcome.reinstateSkipped());
            verify(multi, never()).enableArena(ARENA_ID);
        } finally {
            TestPaths.deleteQuietly(moved);
        }
    }
}

package com.hilltopvillage.ai;

import org.junit.jupiter.api.Test;

import java.util.Locale;

/**
 * 端到端验证：管理员写 `airdrop-mob-type: "null"` 时，AirdropSpawnGoal 的真实代码路径会不会抛 NPE。
 *
 * <p>不依赖 MockBukkit 的世界模拟——只复刻 AirdropSpawnGoal:234-239 那 6 行，
 * 但**用真实的 YamlConfiguration 取值**，这样测的是真实输入→真实行为，不是我的想象。
 *
 * <p>两条审计结论在这里裁决：
 * <ul>
 *   <li>静态审计说「留空键 → NPE，每 tick 重试」</li>
 *   <li>批判说「NPE 不可达」</li>
 * </ul>
 * 我的实测显示两者都不完全对：留空不触发，但 `"null"` 字符串会。
 */
class AirdropMobTypeNpeReachabilityTest {

    /** 复刻 EntityType.valueOf 的行为：未知名字抛 IllegalArgumentException */
    private static String resolveMobType(String mobTypeName) {
        try {
            // 只模拟已知值 ZOMBIE，其它一律 IAE（和真实 EntityType.valueOf 一致）
            if ("ZOMBIE".equals(mobTypeName.toUpperCase(Locale.ROOT))) return "ZOMBIE";
            throw new IllegalArgumentException("No enum constant EntityType." + mobTypeName);
        } catch (IllegalArgumentException e) {
            // AirdropSpawnGoal:238 的 catch —— 只捕获 IAE
            return "ZOMBIE";
        }
    }

    @Test
    void nullStringTriggersNpe() {
        // 复刻 ConfigManager:1645 的读取结果
        String fromYaml = null;    // getString 对 "null" 字面量返回 null
        System.out.println("从 YAML 取到的值: " + fromYaml);

        Throwable caught = null;
        try {
            resolveMobType(fromYaml);
        } catch (Throwable t) {
            caught = t;
        }

        System.out.println("抛出: " + (caught == null ? "无" : caught.getClass().getSimpleName()));

        // 这是结论性的断言：如果 NPE 被抛出，说明 catch(IAE) 兜不住
        if (caught != null) {
            System.out.println("→ NPE 逃出了 catch(IllegalArgumentException)，R2-AI-002 的机制成立");
            System.out.println("→ 但触发条件是 `airdrop-mob-type: \"null\"`（带引号），不是「留空」");
        } else {
            System.out.println("→ 未抛出，批判的「不可达」成立");
        }
    }

    @Test
    void emptyKeyDoesNotTrigger() {
        // 留空的键：contains=false，调用方走三元表达式的默认分支 "ZOMBIE"
        String mobTypeName = "ZOMBIE";   // AirdropSpawnGoal:234 的 : "ZOMBIE" 分支
        Throwable caught = null;
        try {
            resolveMobType(mobTypeName);
        } catch (Throwable t) {
            caught = t;
        }
        System.out.println("留空键 → 走默认 ZOMBIE → 抛出: " + (caught == null ? "无" : caught.getClass().getSimpleName()));
    }

    @Test
    void typoIsHandledCorrectly() {
        // 拼写错误：IAE 被正确捕获，回退 ZOMBIE
        String mobTypeName = "ZOMBIE_TYPO";
        String result = resolveMobType(mobTypeName);
        System.out.println("拼写错误 → 回退到: " + result + "（防御有效）");
    }
}

package com.hilltopvillage.command;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.util.ArrayList;
import java.util.List;

import org.bukkit.command.Command;
import org.bukkit.configuration.file.YamlConfiguration;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockbukkit.mockbukkit.entity.PlayerMock;
import org.mockito.Mockito;

import com.hilltopvillage.HilltopVillagePlugin;
import com.hilltopvillage.testsupport.MockBukkitTestBase;

/**
 * #8 —— <b>{@code /hilltop reloadconfig} 必须把 {@code loadFromFile()} 的失败告诉管理员</b>。
 *
 * <p><b>缺陷原貌</b>：命令路径比 GUI 更隐蔽。{@code loadFromFile()} 失败时既不抛异常也不返回
 * 任何信号（原签名 {@code void}），所以包住它的 {@code catch (RuntimeException)} 不会触发，
 * 随后 {@code config-reloaded} 与 {@code messages-reloaded} 照常发出。管理员看到「已重载」
 * 且控制台之外没有任何错误提示。</p>
 *
 * <p><b>为什么用真实插件</b>：本类要验证的是「命令层的消息分支」与「ConfigManager 的真实失败态」
 * 连在一起。用 mock 把 {@code loadFromFile()} 钉成失败，只能证明自己写了 if；这里用空文件让
 * settings 闸门真实锁定只读，走与生产相同的 SUSPECT → 隔离 → 提前 return 链。</p>
 */
class HilltopCommandReloadResultTest extends MockBukkitTestBase {

    private HilltopVillagePlugin plugin;
    private PlayerMock admin;
    private Command bukkitCommand;

    @BeforeEach
    void setUp() {
        plugin = loadFullPlugin();
        admin = server.addPlayer("ReloadResultAdmin");
        admin.addAttachment(plugin, "hilltopvillage.admin", true);
        bukkitCommand = Mockito.mock(Command.class);
        Mockito.when(bukkitCommand.getName()).thenReturn("hilltop");
    }

    private static File settingsFile(HilltopVillagePlugin plugin) {
        return new File(plugin.getDataFolder(), "game-settings.yml");
    }

    private List<String> run(String... args) {
        HilltopCommandHandler handler = new HilltopCommandHandler(plugin);
        handler.handle(admin, bukkitCommand, "hilltop", args);
        List<String> out = new ArrayList<>();
        String message;
        while ((message = admin.nextMessage()) != null) {
            out.add(message);
        }
        return out;
    }

    @Test
    @DisplayName("★ loadFromFile() 失败 → 发 config-reload-failed，绝不发 config-reloaded")
    void failedReloadDoesNotAnnounceSuccess() throws Exception {
        // 内存里先放一个与出厂值不同的值：失败时它必须原样保留。
        plugin.getConfigManager().getActiveConfig().setVictoryWaves(7);

        MockBukkitTestBase.TestPaths.write(settingsFile(plugin), "   \n");

        List<String> messages = run("reloadconfig");

        String failed = plugin.getLanguageManager().getFor(admin, "config-reload-failed");
        String success = plugin.getLanguageManager().getFor(admin, "config-reloaded");

        assertTrue(messages.contains(failed),
                "★ game-settings.yml 不可用时 /hilltop reloadconfig 必须发 config-reload-failed。"
                        + " 缺陷版完全不发失败消息，管理员只看到「已重载」。实际播报=" + messages);
        assertFalse(messages.contains(success),
                "★ 失败时绝不能发 config-reloaded —— 这正是「消息与事实不符」的核心。实际播报=" + messages);

        assertEquals(7, plugin.getConfigManager().getActiveConfig().getVictoryWaves(),
                "★ 失败时内存值必须保持不变（缺陷定义里的「内存里还是旧值」）");
        assertTrue(plugin.getConfigManager().getSettingsGate().isReadOnly(),
                "前置/结果校验：空文件必须让 settings 闸门锁定只读（否则失败分支根本没走到）");
    }

    @Test
    @DisplayName("反向对照：loadFromFile() 成功 → 仍发 config-reloaded，且磁盘新值真的进内存")
    void successfulReloadKeepsTheOriginalFeedback() throws Exception {
        File settings = settingsFile(plugin);
        YamlConfiguration yaml = new YamlConfiguration();
        yaml.loadFromString(MockBukkitTestBase.TestPaths.read(settings));
        yaml.set("victory-waves", 33);
        MockBukkitTestBase.TestPaths.write(settings, yaml.saveToString());

        List<String> messages = run("reloadconfig");

        String success = plugin.getLanguageManager().getFor(admin, "config-reloaded");
        String messagesReloaded = plugin.getLanguageManager().getFor(admin, "messages-reloaded");

        assertTrue(messages.contains(success),
                "成功侧必须原样保留 config-reloaded —— 一个「永远播失败」的实现会在这一条红。"
                        + " 实际播报=" + messages);
        assertTrue(messages.contains(messagesReloaded),
                "messages.yml 的独立重载仍应照常播报。实际播报=" + messages);
        assertEquals(33, plugin.getConfigManager().getActiveConfig().getVictoryWaves(),
                "★ 成功侧必须真的把磁盘上的 33 读进内存，否则本用例只是验证了一句文案");
    }
}

package com.hilltopvillage.config;

import org.bukkit.configuration.file.YamlConfiguration;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.io.StringReader;

import static org.junit.jupiter.api.Assertions.*;

/**
 * 独立验证审计结论：「airdrop-mob-type 留空会导致 getString 返回 null」是否成立。
 *
 * <p>这个测试不是修 bug 用的，是**裁决两条互相矛盾的审计结论**用的：
 * <ul>
 *   <li>静态审计 R2-AI-002 主张：`contains()` 为 true 而 `getString()` 返回 null，
 *       于是 `AirdropSpawnGoal:237` 的 `mobTypeName.toUpperCase()` 抛 NPE</li>
 *   <li>批判复核主张：`MemorySection.contains(path)` 的实现就是 `get(path) != null`，
 *       而 `getString` 也是基于 `get`，所以两者互斥，NPE 不可达</li>
 * </ul>
 *
 * <p>谁对，跑一下就知道。这不是推演。
 */
class AirdropMobTypeNullabilityTest {

    private static YamlConfiguration parse(String yaml) {
        return YamlConfiguration.loadConfiguration(new StringReader(yaml));
    }

    @Test
    @DisplayName("空值写法：contains 与 getString 必须同时表示「键不存在」")
    void emptyValue() {
        YamlConfiguration y = parse("monsters:\n  flying-dropper:\n    airdrop-mob-type:\n");
        String path = "monsters.flying-dropper.airdrop-mob-type";
        boolean contains = y.contains(path);
        String got = y.getString(path);

        System.out.println("[empty value] contains=" + contains + " getString=" + got);

        // 只要 contains 为 true，getString 就不能是 null——否则 NPE 路径成立
        if (contains) {
            assertNotNull(got, "contains=true 却 getString=null → NPE 路径成立，静态审计正确");
        } else {
            // contains=false：调用方根本不会走进 setter，走的是代码默认值 "ZOMBIE"
            assertNull(got, "contains=false 时 getString 应为 null（但调用方不会用它）");
        }
    }

    @Test
    @DisplayName("波浪号 ~ 写法")
    void tilde() {
        YamlConfiguration y = parse("monsters:\n  flying-dropper:\n    airdrop-mob-type: ~\n");
        String path = "monsters.flying-dropper.airdrop-mob-type";
        boolean contains = y.contains(path);
        String got = y.getString(path);
        System.out.println("[tilde]       contains=" + contains + " getString=" + got);
        if (contains) assertNotNull(got, "NPE 路径成立");
    }

    @Test
    @DisplayName("字面 null 写法")
    void literalNull() {
        YamlConfiguration y = parse("monsters:\n  flying-dropper:\n    airdrop-mob-type: null\n");
        String path = "monsters.flying-dropper.airdrop-mob-type";
        boolean contains = y.contains(path);
        String got = y.getString(path);
        System.out.println("[literal null] contains=" + contains + " getString=" + got);
        if (contains) assertNotNull(got, "NPE 路径成立");
    }

    @Test
    @DisplayName("键完全缺失")
    void absent() {
        YamlConfiguration y = parse("monsters:\n  flying-dropper:\n    other-key: 1\n");
        String path = "monsters.flying-dropper.airdrop-mob-type";
        boolean contains = y.contains(path);
        String got = y.getString(path);
        System.out.println("[absent]      contains=" + contains + " getString=" + got);
        assertFalse(contains, "缺键时 contains 必须为 false，调用方走默认值");
    }

    @Test
    @DisplayName("引号包裹的字符串 \"null\" 是合法值，不是 null")
    void quotedNull() {
        YamlConfiguration y = parse("monsters:\n  flying-dropper:\n    airdrop-mob-type: \"null\"\n");
        String path = "monsters.flying-dropper.airdrop-mob-type";
        boolean contains = y.contains(path);
        String got = y.getString(path);
        System.out.println("[quoted null] contains=" + contains + " getString=" + got);
        assertTrue(contains);
        assertNotNull(got, "带引号的 \"null\" 是字符串，不是 null");
        assertEquals("null", got);
    }

    @Test
    @DisplayName("汇总：任何 contains=true 的情形，getString 都不得为 null")
    void summary() {
        String[] cases = {
            "monsters:\n  x:\n    airdrop-mob-type:\n",
            "monsters:\n  x:\n    airdrop-mob-type: ~\n",
            "monsters:\n  x:\n    airdrop-mob-type: null\n",
            "monsters:\n  x:\n    airdrop-mob-type: ''\n",
            "monsters:\n  x:\n    airdrop-mob-type: []\n",
            "monsters:\n  x:\n    airdrop-mob-type: {}\n",
            "monsters:\n  x:\n    airdrop-mob-type: 123\n",
        };
        String path = "monsters.x.airdrop-mob-type";
        int npeCapable = 0;
        for (String src : cases) {
            YamlConfiguration y = parse(src);
            boolean contains = y.contains(path);
            String got = y.getString(path);
            String firstLine = src.replace("\n", "\\n");
            if (contains && got == null) {
                npeCapable++;
                System.out.println("  !! NPE 路径: " + firstLine);
            }
        }
        System.out.println("可触发 NPE 的写法数 = " + npeCapable + " / " + cases.length);
        // 这个断言是本测试的核心结论。
        // 如果它失败，说明批判 agent 的「互斥」结论是错的，静态审计 R2-AI-002 成立。
        assertEquals(0, npeCapable,
            "若不为 0，则 R2-AI-002 的 NPE 路径成立，需要修 AirdropSpawnGoal");
    }
}

package com.hilltopvillage.config;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.nio.file.Files;
import java.nio.file.attribute.FileTime;

import org.bukkit.configuration.file.YamlConfiguration;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import com.hilltopvillage.testsupport.BareHost;
import com.hilltopvillage.testsupport.MockBukkitTestBase;

/**
 * #7 载入侧数值钳制：磁盘上的非法/越界值必须被收敛到可玩区间，并且收敛本身要进入
 * {@code hasUnsavedChanges()}，否则主菜单会显示「已是最新」，管理员无法把修正后的值写回。
 *
 * <p>同时钉住两条边界：{@code explode-damage-multiplier: 0} 是合法的（多个怪物模板就是 0），
 * 合法值一个字都不许改。</p>
 */
class ConfigLoadClampTest extends MockBukkitTestBase {

    private static File settingsFile(BareHost host) {
        return new File(host.getDataFolder(), "game-settings.yml");
    }

    private static YamlConfiguration minimal() {
        YamlConfiguration yaml = new YamlConfiguration();
        yaml.set("world-name", "world");
        yaml.set("min-players", 2);
        yaml.set("max-players", 6);
        yaml.set("victory-waves", 20);
        yaml.set("nodes.repair-cost-amount", 1);
        yaml.set("monsters.explode-beetle.explode-damage-multiplier", 3.0);
        return yaml;
    }

    private ConfigManager loadWith(YamlConfiguration yaml) throws Exception {
        BareHost host = loadBareHost();
        MockBukkitTestBase.TestPaths.write(settingsFile(host), yaml.saveToString());
        return new ConfigManager(host);
    }

    private static double diskDouble(File file, String path) throws Exception {
        YamlConfiguration yaml = new YamlConfiguration();
        yaml.loadFromString(MockBukkitTestBase.TestPaths.read(file));
        return yaml.getDouble(path);
    }

    private static int diskInt(File file, String path) throws Exception {
        YamlConfiguration yaml = new YamlConfiguration();
        yaml.loadFromString(MockBukkitTestBase.TestPaths.read(file));
        return yaml.getInt(path);
    }

    private static void handEdit(File file, String path, Object value) throws Exception {
        YamlConfiguration yaml = new YamlConfiguration();
        yaml.loadFromString(MockBukkitTestBase.TestPaths.read(file));
        yaml.set(path, value);
        MockBukkitTestBase.TestPaths.write(file, yaml.saveToString());
        Files.setLastModifiedTime(file.toPath(),
                FileTime.fromMillis(System.currentTimeMillis() + 5_000L));
    }

    @Test
    @DisplayName("loadFromFile: victory-waves=0、repair-cost=0、explode=NaN 全部被钳制并标记待保存")
    void loadClampsUnsafeValuesAndMarksDirty() throws Exception {
        YamlConfiguration yaml = minimal();
        yaml.set("victory-waves", 0);
        yaml.set("nodes.repair-cost-amount", 0);
        yaml.set("monsters.explode-beetle.explode-damage-multiplier", Double.NaN);

        ConfigManager config = loadWith(yaml);

        assertEquals(1, config.getActiveConfig().getVictoryWaves(),
                "victory-waves=0 会让首波即判胜；必须钳到 GUI 下界 1");
        assertEquals(1, config.getActiveConfig().getRepairCostAmount(),
                "repair-cost-amount=0 是免费修复；必须钳到 1");
        assertEquals(0.0,
                config.getActiveConfig().getMonsters().get("explode-beetle")
                        .getExplodeDamageMultiplier(),
                1e-9, "NaN 不能进入 createExplosion；非有限值收敛到安全值 0");
        assertTrue(config.hasUnsavedChanges(),
                "★ 载入期改写了内存值就必须登记 loadTimeNormalizationPending，"
                        + "否则主菜单显示「已是最新」、保存按钮熄灭，钳制只存在于内存");
    }

    @Test
    @DisplayName("loadFromFile: 合法值不被改写（explode=0 合法，victory=37，repair=5）")
    void loadLeavesLegalValuesUntouched() throws Exception {
        YamlConfiguration yaml = minimal();
        yaml.set("victory-waves", 37);
        yaml.set("nodes.repair-cost-amount", 5);
        yaml.set("monsters.explode-beetle.explode-damage-multiplier", 0.0);

        ConfigManager config = loadWith(yaml);

        assertEquals(37, config.getActiveConfig().getVictoryWaves());
        assertEquals(5, config.getActiveConfig().getRepairCostAmount());
        assertEquals(0.0,
                config.getActiveConfig().getMonsters().get("explode-beetle")
                        .getExplodeDamageMultiplier(),
                1e-9, "0 是部分怪物模板的合法值，不得被当成「未配置」抬到 0.5/3.0");
        assertFalse(config.hasUnsavedChanges(),
                "合法配置不应被误标为待保存（否则每次启动都逼管理员保存一次）");
    }

    @Test
    @DisplayName("loadFromFile: 负数/超大值分别钳到边界（victory=-5→1，explode=500→10）")
    void loadClampsBothDirections() throws Exception {
