import com.hilltopvillage.config.ConfigManager;
import com.hilltopvillage.testsupport.BareHost;
import com.hilltopvillage.testsupport.MockBukkitTestBase;
import com.hilltopvillage.util.LanguageManager;

/**
 * #8 —— <b>主菜单的「加载配置文件」必须按 {@code loadFromFile()} 的真实结果发消息</b>。
 *
 * <p><b>缺陷原貌</b>：{@code MainConfigMenu} 的 CRAFTING_TABLE 动作先调
 * {@code configManager.loadFromFile();} 丢掉结果，随后<b>无条件</b>发
 * {@code config.menu.main.reloaded-msg} 并播成功音。而 {@code loadFromFile()} 在
 * {@code game-settings.yml} 不可用（或本进程已因隔离而只读）时只打一条 SEVERE、
 * 保留内存旧值就 {@code return} —— 管理员看到「已从 game-settings.yml 重新加载」，
 * 实际什么都没重载。</p>
 *
 * <p><b>本类证明什么</b>：同一条点击链跑「成功」与「失败」两侧，并两个方向都断言。
 * 失败侧用真实 {@link ConfigManager} + 空文件（{@code YamlFiles} 的 SUSPECT 分支），
 * 与 {@code ConfigManagerTest} 的降级夹具同源；成功侧还必须证明磁盘新值真的进了内存，
 * 否则「只改消息、不改加载」的实现也能让消息断言变绿。</p>
 */
class MainConfigMenuReloadResultTest extends MockBukkitTestBase {

    /** {@code bottomRow = 45}，reload 按钮在 {@code bottomRow + 4}。 */
    private static final int RELOAD_SLOT = 49;

    private BareHost host;
    private MockedStatic<JavaPlugin> lookup;
    private LanguageManager lang;
    private PlayerMock admin;

    @BeforeEach
    void setUp() {
        host = loadBareHost();
        lookup = MenuTestSupport.pluginLookup(host);
        // 原样回传 key：成功文案与失败文案必须可区分，否则断言「播了哪一条」形同虚设。
        lang = mock(LanguageManager.class);
        when(lang.getFor(any(), anyString())).thenAnswer(inv -> inv.getArgument(1));
        when(lang.getFor(any(), anyString(), any(Object[].class))).thenAnswer(inv -> inv.getArgument(1));
        admin = server.addPlayer("reload-result-admin");
    }

    @AfterEach
    void tearDown() {
        if (lookup != null) {
            lookup.close();
        }
    }

    private static File settingsFile(BareHost host) {
        return new File(host.getDataFolder(), "game-settings.yml");
    }

    private MainConfigMenu openMainMenu(ConfigManager config) {
        MainConfigMenu menu = new MainConfigMenu(admin, config, lang);
        menu.open();
        assertTrue(menu.clickActions.containsKey(RELOAD_SLOT),
                "夹具前提：slot " + RELOAD_SLOT + " 必须是「加载配置文件」按钮。"
                        + " 若菜单布局变了，本用例要在这里先红，而不是在后面假绿");
        return menu;
    }

    private void drainSounds() {
        admin.getHeardSounds().clear();
    }

    @Test
    @DisplayName("★ loadFromFile() 失败 → 发 reload-failed + 失败音，绝不发 reloaded-msg")
    void failedReloadReportsFailureInsteadOfSuccess() throws Exception {
        ConfigManager config = new ConfigManager(host);
        // 内存里先放一个与出厂值不同的值：失败时它必须原样保留，不能被重建/覆盖。
        config.getActiveConfig().setVictoryWaves(7);

        // 构造之后再破坏文件：空文件会让 YamlFiles 判 SUSPECT，settings 闸门锁定只读。
        MockBukkitTestBase.TestPaths.write(settingsFile(host), "   \n");

        MainConfigMenu menu = openMainMenu(config);
        drainSounds();

        MenuTestSupport.click(admin, menu, RELOAD_SLOT, ClickType.LEFT);
        server.getScheduler().performTicks(2);

        assertEquals("config.menu.main.reload-failed", admin.nextMessage(),
                "★ game-settings.yml 不可用时必须发 reload-failed（而不是 reloaded-msg）。"
                        + " 缺陷版在这里发的是 reloaded-msg —— 管理员会以为磁盘值已经生效");
        assertEquals(null, admin.nextMessage(),
                "失败时不得再发任何「成功」尾巴；成功路径只应有一条 reloaded-msg");

        assertEquals(1, admin.getHeardSounds().size(),
                "失败时必须恰好播一次音效（0 次 = 静默，2 次 = 成功/失败音叠加）");
        assertEquals(Sound.BLOCK_ANVIL_LAND.getKey().getKey(),
                admin.getHeardSounds().get(0).getSound(),
                "失败音必须是铁砧落地；缺陷版播的是 BLOCK_NOTE_BLOCK_PLING（成功音）");

        assertEquals(7, config.getActiveConfig().getVictoryWaves(),
                "★ 失败时内存值必须保持不变（缺陷定义里的「内存里还是旧值」）");
        assertTrue(config.getSettingsGate().isReadOnly(),
                "前置/结果校验：空文件必须让 settings 闸门锁定只读（否则失败分支根本没走到）");
    }

    @Test
    @DisplayName("反向对照：loadFromFile() 成功 → 仍发 reloaded-msg + 成功音，且磁盘新值真的进内存")
    void successfulReloadKeepsTheOriginalFeedback() throws Exception {
        ConfigManager config = new ConfigManager(host);

        // 在构造之后改磁盘：只有真的重新读盘，内存才会变成 12。
        File settings = settingsFile(host);
        YamlConfiguration yaml = new YamlConfiguration();
        yaml.loadFromString(MockBukkitTestBase.TestPaths.read(settings));
        yaml.set("victory-waves", 12);
        MockBukkitTestBase.TestPaths.write(settings, yaml.saveToString());

        MainConfigMenu menu = openMainMenu(config);
        drainSounds();

        MenuTestSupport.click(admin, menu, RELOAD_SLOT, ClickType.LEFT);
        server.getScheduler().performTicks(2);

        assertEquals("config.menu.main.reloaded-msg", admin.nextMessage(),
                "成功侧必须原样保留 reloaded-msg —— 一个「永远播失败」的实现会在这一条红");
        assertEquals(null, admin.nextMessage(), "成功路径不应额外发失败消息");
        assertEquals(12, config.getActiveConfig().getVictoryWaves(),
                "★ 成功侧必须真的把磁盘上的 12 读进内存，否则本用例只是验证了一句文案");

        assertEquals(1, admin.getHeardSounds().size(), "成功时恰好一次成功音效");
        assertEquals(Sound.BLOCK_NOTE_BLOCK_PLING.getKey().getKey(),
                admin.getHeardSounds().get(0).getSound(),
                "成功音必须仍是 PLING；实际：" + admin.getHeardSounds().get(0).getSound());
        assertNotNull(menu.getInventory().getItem(RELOAD_SLOT),
                "reopen() 后 reload 槽位仍应有物品");
    }
}

package com.hilltopvillage.doc;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.lang.reflect.InvocationHandler;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

/**
 * F7 回归测试：{@code commands.md} 必须走「同目录临时文件 + 原子替换」，失败时保留旧文档。
 *
 * <p><b>缺陷行为</b>：{@code generate()} 的异步块用 {@code Files.write(docFile.toPath(), ...)}
 * 直接写目标文件。该调用会先截断目标再写，写入过程（崩溃、磁盘满、权限变化、并发读）
 * 失败就留下空文件或半截文档；而生成只在启动时跑一次，没有重试，也没有旧版本可回退。</p>
 *
 * <p><b>为什么用反射而不是直接调用</b>：本测试必须在<b>修复前</b>的代码上编译通过。
 * 修复引入的 {@code writeAtomically(Path, byte[])} 与移动接缝在修复前并不存在，
 * 直接引用会变成编译错误，而编译错误不是红测。按方法名反射后：</p>
 * <ul>
 *   <li>修复前 —— {@link #successfulWriteReplacesTargetAndLeavesNoTempFile()} 与
 *       {@link #failedMoveKeepsOldDocumentAndCleansUpTempFile()} 在查找方法时以清晰的
 *       {@link AssertionError} 失败；{@link #asyncBlockNoLongerTruncatesTheTargetInPlace()}
 *       直接断言「源码里仍是 Files.write(docFile)」而失败。</li>
 *   <li>修复后 —— 三条都通过：临时文件先写满、移动用 ATOMIC_MOVE、移动失败时旧目标原样保留
 *       且临时文件被清理。</li>
 * </ul>
 *
 * <p><b>不依赖时序</b>：没有 sleep，没有并发写盘竞态。移动接缝是同步调用的，
 * 「移动发生的那一刻」被临时文件与旧目标的实际内容直接观测。</p>
 */
@DisplayName("CommandsDocumentGenerator — commands.md 原子写（F7）")
class CommandsDocumentAtomicWriteTest {

    /** 生产源文件；surefire 的工作目录是模块根目录（与 AirdropSpawnGoalTest 的源码守卫一致）。 */
    private static final Path PRODUCTION_SOURCE =
            Path.of("src/main/java/com/hilltopvillage/doc/CommandsDocumentGenerator.java");

    // ------------------------------------------------------------------ 1. 成功路径

    @Test
    @DisplayName("成功路径：整份替换目标文档，成功后不残留临时文件")
    void successfulWriteReplacesTargetAndLeavesNoTempFile() throws Exception {
        Path dir = Files.createTempDirectory("f7-atomic-success");
        Path target = dir.resolve("commands.md");
        Files.writeString(target, "旧文档：整份旧内容\n", StandardCharsets.UTF_8);
        String newDocument = "# 村民守卫战PLUS — 命令文档\n\n整份新内容。\n";

        Method writeAtomically = findWriteAtomically(2);
        try {
            writeAtomically.invoke(null, target, newDocument.getBytes(StandardCharsets.UTF_8));
        } catch (InvocationTargetException failure) {
            throw new AssertionError("writeAtomically 在正常路径不应抛异常，实际抛了 " + failure.getCause(),
                    failure.getCause());
        }

        assertEquals(newDocument, Files.readString(target, StandardCharsets.UTF_8),
                "原子写成功后目标文档必须是完整的新内容");
        assertEquals(List.of("commands.md"), listFileNames(dir),
                "同目录必须只剩目标文档：临时文件若残留，每次服务器启动都会堆一个 .tmp；"
                        + "实际残留：" + listFileNames(dir));
    }

    // ------------------------------------------------------------------ 2. 移动失败路径

    @Test
    @DisplayName("移动失败：旧文档原样保留，临时文件被清理，IOException 抛给调用方")
    void failedMoveKeepsOldDocumentAndCleansUpTempFile() throws Exception {
        Path dir = Files.createTempDirectory("f7-atomic-failure");
        Path target = dir.resolve("commands.md");
        String oldDocument = "# 旧文档\n\n这一行必须在失败的写入之后仍然存在。\n";
        Files.writeString(target, oldDocument, StandardCharsets.UTF_8);
        String newDocument = "# 新文档\n\n这份内容不应落盘。\n";
        byte[] newContent = newDocument.getBytes(StandardCharsets.UTF_8);

        Method writeAtomically = findWriteAtomically(3);
        Class<?> moveStepType = writeAtomically.getParameterTypes()[2];
        assertTrue(moveStepType.isInterface(),
                "第三参数应为可注入的移动接缝（函数式接口），实际是 " + moveStepType.getName());

        AtomicReference<Path> sourceAtMove = new AtomicReference<>();
        AtomicReference<Path> targetAtMove = new AtomicReference<>();
        AtomicReference<String> sourceContentAtMove = new AtomicReference<>();
        AtomicReference<String> targetContentAtMove = new AtomicReference<>();

        InvocationHandler failingMove = (proxy, method, args) -> {
            if (method.getDeclaringClass() == Object.class) {
                return switch (method.getName()) {
                    case "toString" -> "failing-move-seam";
                    case "hashCode" -> System.identityHashCode(proxy);
                    case "equals" -> proxy == args[0];
                    default -> null;
                };
            }
            Path source = (Path) args[0];
            Path destination = (Path) args[1];
            sourceAtMove.set(source);
            targetAtMove.set(destination);
            sourceContentAtMove.set(readIfExists(source));
            targetContentAtMove.set(readIfExists(destination));
            throw new IOException("注入的移动失败（F7 故障注入）");
        };
        Object failingMoveStep = Proxy.newProxyInstance(
                CommandsDocumentGenerator.class.getClassLoader(),
                new Class<?>[] {moveStepType},
                failingMove);

        Throwable thrown = assertThrows(Throwable.class, () -> {
            try {
                writeAtomically.invoke(null, target, newContent, failingMoveStep);
            } catch (InvocationTargetException invocation) {
                throw invocation.getCause();
            }
        });
        assertTrue(thrown instanceof IOException,
                "移动失败必须以 IOException 抛给调用方（generate() 的 catch 才能打 WARNING）；实际：" + thrown);

        // ---- 移动发生的那一刻：这正是 F7 要证明的窗口 ----
        assertNotNull(sourceAtMove.get(),
                "生产路径没有调用移动接缝 —— 说明它没有「先写临时文件、再替换目标」");
        Path movedFrom = sourceAtMove.get().toAbsolutePath().normalize();
        Path movedTo = targetAtMove.get().toAbsolutePath().normalize();
        assertEquals(target.toAbsolutePath().normalize(), movedTo,
                "移动的目标必须是 commands.md 本身");
        assertNotEquals(movedTo, movedFrom, "移动的源不能是目标文件本身（那就是就地截断写）");
        assertEquals(target.toAbsolutePath().normalize().getParent(), movedFrom.getParent(),
                "临时文件必须与目标同目录（跨分区/跨目录会让 ATOMIC_MOVE 失效）；实际：" + movedFrom);
        assertEquals(newDocument, sourceContentAtMove.get(),
                "移动之前，临时文件里必须已经是完整的新内容");
        assertEquals(oldDocument, targetContentAtMove.get(),
                "移动之前目标文档就已经被改写/截断 —— 这正是 F7 的缺陷："
                        + "直接 Files.write 目标文件时，崩溃/磁盘满会留下空文件或半截文档");

        // ---- 失败之后：旧文档可用，临时文件不残留 ----
        assertEquals(oldDocument, Files.readString(target, StandardCharsets.UTF_8),
                "移动失败后旧文档必须原样保留（这是「没有重试、启动只生成一次」场景下唯一的回退版本）");
        assertEquals(List.of("commands.md"), listFileNames(dir),
                "失败路径必须清理临时文件，否则每次失败都会在数据目录里留下垃圾；"
                        + "实际残留：" + listFileNames(dir));
    }

    // ------------------------------------------------------------------ 3. 源码守卫

    @Test
    @DisplayName("无插件的重载也不得吞掉降级告警（类名 logger 兜底）")
    void twoArgOverloadDoesNotSwallowTheFallbackWarning() throws Exception {
        String source = Files.readString(PRODUCTION_SOURCE, StandardCharsets.UTF_8);
        int start = source.indexOf("static void writeAtomically(Path target, byte[] content) throws IOException {");
        assertTrue(start >= 0, "找不到两参数的 writeAtomically 重载");
        int end = source.indexOf("static void writeAtomically(Path target, byte[] content, MoveStep", start);
        String body = source.substring(start, end);

        assertFalse(body.contains("message -> { }"),
                "两参数重载把降级告警丢进了空 Consumer —— 那条路径上的降级会完全无声，"
                        + "而 javadoc 承诺「降级会记一条 WARNING」；这个重载是最容易被顺手调用的入口");
        assertTrue(body.contains("Logger.getLogger"),
                "两参数重载应退回到类名 logger 记录降级告警（它拿不到插件 logger）");
    }

    @Test
    @DisplayName("源码守卫：异步块不再直接 Files.write 目标，替换必须使用 ATOMIC_MOVE")
    void asyncBlockNoLongerTruncatesTheTargetInPlace() throws Exception {
        String source = Files.readString(PRODUCTION_SOURCE, StandardCharsets.UTF_8);

        assertFalse(source.contains("Files.write(docFile"),
                "异步块仍在直接 Files.write 目标 commands.md —— 截断写没有临时文件，"
                        + "崩溃/磁盘满/权限变化会留下空文档或半截文档，且没有旧版本可回退");
        assertTrue(source.contains("writeAtomically("),
                "commands.md 必须通过 writeAtomically(...) 写盘");
        assertTrue(source.contains("ATOMIC_MOVE"),
                "替换步骤必须使用 StandardCopyOption.ATOMIC_MOVE（单用 REPLACE_EXISTING 在 Windows 上不是原子替换）");
        assertTrue(source.contains("AtomicMoveNotSupportedException"),
                "只允许对 AtomicMoveNotSupportedException 降级为非原子 move，"
                        + "其他 IOException 必须原样抛出（否则失败被吞掉，旧文档状态无法判断）");
    }

    // ------------------------------------------------------------------ 工具

    /**
     * 按名字 + 参数个数查找 {@code writeAtomically}。
     *
     * <p>刻意用反射：修复前该方法不存在，本测试仍能编译，失败原因是清晰的
     * {@link AssertionError} 而不是编译错误。</p>
     */
    private static Method findWriteAtomically(int parameterCount) {
        Method found = Arrays.stream(CommandsDocumentGenerator.class.getDeclaredMethods())
                .filter(method -> method.getName().equals("writeAtomically"))
                .filter(method -> method.getParameterCount() == parameterCount)
                .filter(method -> method.getParameterTypes()[0] == Path.class)
                .findFirst()
                .orElse(null);
        assertNotNull(found,
                "CommandsDocumentGenerator 缺少 writeAtomically(" + parameterCount + " 参数)："
                        + "F7 的修复要求把 commands.md 改成「同目录临时文件 + 原子替换」，"
                        + "并公开一个包内可见的移动接缝供故障注入；当前生产代码仍是直接截断写目标文件");
        found.setAccessible(true);
        return found;
    }

    private static String readIfExists(Path path) {
        try {
            return Files.readString(path, StandardCharsets.UTF_8);
        } catch (IOException unreadable) {
            return null;
        }
    }

    private static List<String> listFileNames(Path dir) throws IOException {
        List<String> names = new ArrayList<>();
        try (var stream = Files.list(dir)) {
            stream.forEach(path -> names.add(path.getFileName().toString()));
        }
        names.sort(String::compareTo);
        return names;
    }
}

package com.hilltopvillage.doc;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

/**
 * F7 缺陷 3：{@code writeAtomically} 的并发写必须被串行化。
 *
 * <p><b>缺陷</b>：{@code grep "synchronized|Lock|concurrent"} 在生成器里零命中。两个线程
 * 各自 {@code createTempFile}、各自 {@code move}，两次写入的「移动」窗口可以重叠：
 * 在 {@code ATOMIC_MOVE} 主路径上表现为「后移动者赢，先移动者的写入被静默丢弃」，
 * 在非原子降级路径上窗口更大（先删目标再改名），重叠会真的丢文件。</p>
 *
 * <p><b>本测法为什么不是「测桩」</b>：被测对象是 {@link CommandsDocumentGenerator#writeAtomically}
 * 的<b>串行化性质</b>本身。{@code MoveStep} 在这里只用来「把移动拉长到可观测的 80ms」，
 * 它是否被打桩与被测性质无关 —— 断言的是「两个线程能否同时处在写盘临界区内」，
 * 而临界区和锁都是真实的生产代码。</p>
 *
 * <p><b>为什么不用「并发写后校验文件内容」的测法</b>：单文件替换在 Windows/POSIX 上都是
 * 一次 rename，内容永远是某一份完整的文档，因此内容断言在修复前也会通过 —— 那种用例
 * 无法暴露缺陷，只会给出「并发没问题」的假结论。真正可观测的差异是临界区重叠。</p>
 */
@DisplayName("CommandsDocumentGenerator — 并发写串行化（F7）")
class CommandsDocumentConcurrencyTest {

    private static final int THREADS = 4;
    private static final long MOVE_DWELL_MILLIS = 80L;

    @Test
    @DisplayName("多个线程同时写同一目标时，写盘临界区里最多只有一个线程")
    void concurrentWritesNeverOverlapInsideTheCriticalSection() throws Exception {
        Path dir = Files.createTempDirectory("f7-concurrent");
        Path target = dir.resolve("commands.md");
        Files.writeString(target, "# 初始文档\n", StandardCharsets.UTF_8);

        Method writeAtomically = findWriteAtomicallyWithSeam();
        Class<?> moveStepType = writeAtomically.getParameterTypes()[2];

        AtomicInteger inCriticalSection = new AtomicInteger();
        AtomicInteger maxObserved = new AtomicInteger();
        AtomicInteger movesCompleted = new AtomicInteger();
        List<Throwable> failures = new ArrayList<>();

        // 让所有线程尽量同时起跑：barrier 只负责起跑同步，不负责临界区同步。
        CountDownLatch ready = new CountDownLatch(THREADS);
        CountDownLatch go = new CountDownLatch(1);

        InvocationHandler dwellingMove = (proxy, method, args) -> {
            if (method.getDeclaringClass() == Object.class) {
                return switch (method.getName()) {
                    case "toString" -> "dwelling-move-seam";
                    case "hashCode" -> System.identityHashCode(proxy);
                    case "equals" -> proxy == args[0];
                    default -> null;
                };
            }
            int concurrency = inCriticalSection.incrementAndGet();
            try {
                maxObserved.accumulateAndGet(concurrency, Math::max);
                Thread.sleep(MOVE_DWELL_MILLIS);
                Files.move((Path) args[0], (Path) args[1],
                        java.nio.file.StandardCopyOption.REPLACE_EXISTING,
                        java.nio.file.StandardCopyOption.ATOMIC_MOVE);
                movesCompleted.incrementAndGet();
            } finally {
                inCriticalSection.decrementAndGet();
            }
            return null;
        };
        Object moveStep = Proxy.newProxyInstance(
                CommandsDocumentGenerator.class.getClassLoader(),
                new Class<?>[] {moveStepType},
                dwellingMove);

        List<Thread> threads = new ArrayList<>();
        for (int i = 0; i < THREADS; i++) {
            byte[] content = ("# 并发写入 #" + i + "\n").getBytes(StandardCharsets.UTF_8);
            Thread thread = new Thread(() -> {
                try {
                    ready.countDown();
                    go.await();
                    writeAtomically.invoke(null, target, content, moveStep);
                } catch (java.lang.reflect.InvocationTargetException wrapped) {
                    synchronized (failures) {
                        failures.add(wrapped.getCause());
                    }
                } catch (Throwable other) {
                    synchronized (failures) {
                        failures.add(other);
                    }
                }
            }, "f7-writer-" + i);
            thread.start();
            threads.add(thread);
        }

        assertTrue(ready.await(10, TimeUnit.SECONDS), "前置条件：" + THREADS + " 个写线程应在 10s 内全部就绪");
        go.countDown();
        for (Thread thread : threads) {
            thread.join(30_000L);
            assertTrue(!thread.isAlive(), "写线程 " + thread.getName() + " 在 30s 内未结束 —— 疑似死锁");
        }

        assertEquals(List.of(), failures,
                "并发写不应出现任何异常：串行化之后每个线程都应正常完成；实际失败：" + failures);
        assertEquals(THREADS, movesCompleted.get(),
                "每个线程都应完成自己的那次替换，实际只有 " + movesCompleted.get() + " 次");

        assertEquals(1, maxObserved.get(),
                "观测到 " + maxObserved.get() + " 个线程同时处在写盘临界区内。"
                        + "writeAtomically 未加锁时，两个线程可以同时 createTempFile + move，"
                        + "在非原子降级路径（先删目标再改名）上这会真的丢文件；"
                        + "主路径上也表现为后移动者的写入静默覆盖先移动者");
    }

    @Test
    @DisplayName("源守卫（补充）：临界区由显式的 lock()/unlock() 包围，不是只写了个「synchronized」字样")
    void writeAtomicallyIsGuardedByALock() throws Exception {
        String source = Files.readString(
                Path.of("src/main/java/com/hilltopvillage/doc/CommandsDocumentGenerator.java"),
                StandardCharsets.UTF_8);

        // 这条只是补充守卫：上面的行为测试才是判据。它便宜地挡住「整段锁被删掉」这类改动。
        assertTrue(source.contains(".lock()") && source.contains(".unlock()"),
                "CommandsDocumentGenerator 里没有成对的 lock()/unlock() —— "
                        + "writeAtomically 对并发写没有任何处理（F7 缺陷 3）");
    }

    private static Method findWriteAtomicallyWithSeam() {
        Method found = Arrays.stream(CommandsDocumentGenerator.class.getDeclaredMethods())
                .filter(method -> method.getName().equals("writeAtomically"))
                .filter(method -> method.getParameterCount() == 3)
                .filter(method -> method.getParameterTypes()[0] == Path.class)
                .findFirst()
                .orElse(null);
        assertNotNull(found, "CommandsDocumentGenerator 缺少 writeAtomically(Path, byte[], MoveStep) 接缝");
        found.setAccessible(true);
        return found;
    }
}

package com.hilltopvillage.doc;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.io.IOException;
import java.lang.reflect.InvocationHandler;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.function.Consumer;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import com.hilltopvillage.testsupport.MockBukkitTestBase;

/**
 * F7 缺陷 1 + 缺陷 2 的回归测试：<b>直接执行生产代码里的降级分支</b>。
 *
 * <p><b>为什么不能复用 {@link CommandsDocumentAtomicWriteTest}</b>：那条用例注入的
 * {@code MoveStep} 替换的是整个「移动」这一步，异常在任何文件被删除之前就抛出了，
 * 所以 {@code moveIntoPlace}（含 {@code catch (AtomicMoveNotSupportedException)} 分支）
 * <b>在全部测试里一次都没被执行过</b>。它断言的是桩的行为，不是生产代码的行为。</p>
 *
 * <p><b>本类的测法</b>：把「真正执行原子移动的一步」抽成 {@code AtomicMover} 接缝，
 * 注入物只做一件事 —— <b>抛 {@link AtomicMoveNotSupportedException} 把控制流推进 catch 分支</b>；
 * catch 分支里的全部逻辑（降级为非原子 {@code Files.move}、失败上抛、降级 WARNING）
 * 都是真实生产代码，在真实文件系统上跑。这是「注入触发条件」而不是「注入被测逻辑」。</p>
 *
 * <p><b>为什么不构造真实的 {@code AtomicMoveNotSupportedException}</b>：它只在
 * 「同目录/同卷 rename 无法原子完成」时由 JDK 抛出，而本类的临时文件与目标同目录，
 * 在本地 NTFS/ext4/APFS 上永远不会触发。真实场景不可造 ⇒ 只能注入触发条件，
 * 但<b>被测逻辑必须是真的</b>。</p>
 */
@DisplayName("CommandsDocumentGenerator — ATOMIC_MOVE 降级路径的真实行为（F7）")
class CommandsDocumentFallbackTest extends MockBukkitTestBase {

    /** 生产源文件；surefire 的工作目录是模块根目录。 */
    private static final Path PRODUCTION_SOURCE =
            Path.of("src/main/java/com/hilltopvillage/doc/CommandsDocumentGenerator.java");

    // ------------------------------------------------------------------ 1. 降级成功路径

    @Test
    @DisplayName("ATOMIC_MOVE 被拒 → 生产降级分支真的执行非原子移动，新文档落盘并记降级 WARNING")
    void atomicMoveRejectionRunsTheRealNonAtomicFallback() throws Throwable {
        Path dir = Files.createTempDirectory("f7-fallback-ok");
        Path target = dir.resolve("commands.md");
        String oldDocument = "# 旧文档\n\n这份内容会在降级移动成功后消失（非原子 move 的固有语义）。\n";
        String newDocument = "# 新文档\n\n降级分支必须把这份内容真的搬到位。\n";
        Files.writeString(target, oldDocument, StandardCharsets.UTF_8);
        Path staged = dir.resolve("commands.md.staged.tmp");
        Files.writeString(staged, newDocument, StandardCharsets.UTF_8);

        List<String> warnings = new ArrayList<>();
        invokeMoveIntoPlace(staged, target, atomicMoverRejectingAtomicMove(), warnings);

        assertEquals(newDocument, Files.readString(target, StandardCharsets.UTF_8),
                "降级分支必须真的把暂存文件搬成目标文档 —— 若这里仍是旧文档，说明 catch 分支没有执行移动");
        assertFalse(Files.exists(staged),
                "降级移动成功后暂存文件应已不存在（它被搬走了）；实际仍存在：" + staged);
        assertEquals(1, warnings.size(),
                "降级必须是可观测的：进入非原子路径要记一条 WARNING（缺陷 1 要求），实际：" + warnings);
        assertTrue(warnings.get(0).contains("ATOMIC_MOVE"),
                "降级 WARNING 必须点名 ATOMIC_MOVE 不受支持，否则运维无法判断文件系统有问题；实际：" + warnings.get(0));
    }

    // ------------------------------------------------------------------ 2. 降级失败路径

    @Test
    @DisplayName("降级移动自身失败 → IOException 原样上抛、降级已记 WARNING、目标侧不被破坏")
    void failingFallbackPropagatesAndDoesNotSwallowTheError() throws Throwable {
        Path dir = Files.createTempDirectory("f7-fallback-fail");
        // 目标是一个**非空目录**：非原子 Files.move(REPLACE_EXISTING) 必然失败
        // （Windows: RemoveDirectory → ERROR_DIR_NOT_EMPTY；POSIX: rename → ENOTEMPTY）。
        Path target = dir.resolve("commands.md");
        Files.createDirectory(target);
        Path occupant = target.resolve("keep.txt");
        Files.writeString(occupant, "目标目录里的内容必须原样保留\n", StandardCharsets.UTF_8);
        Path staged = dir.resolve("commands.md.staged.tmp");
        Files.writeString(staged, "# 新文档\n", StandardCharsets.UTF_8);

        List<String> warnings = new ArrayList<>();
        Throwable thrown = assertThrows(Throwable.class,
                () -> invokeMoveIntoPlace(staged, target, atomicMoverRejectingAtomicMove(), warnings),
                "降级移动失败必须把异常抛给调用方（generate() 的 catch 才能记 WARNING），不得吞掉");

        assertTrue(thrown instanceof IOException,
                "降级失败必须以 IOException 形式上抛；实际：" + thrown);
        assertFalse(thrown instanceof AtomicMoveNotSupportedException,
                "上抛的必须是降级移动（真实文件系统）的失败，而不是注入的触发条件泄漏出来 —— "
                        + "若这里看到 AtomicMoveNotSupportedException，说明生产代码没走 catch 分支；实际：" + thrown);

        assertTrue(Files.isDirectory(target),
                "降级移动失败后目标仍是那个目录（本次失败不应把目标换成文件）");
        assertEquals("目标目录里的内容必须原样保留\n",
                Files.readString(occupant, StandardCharsets.UTF_8),
                "降级移动失败不得破坏目标侧已有的内容");

        assertEquals(1, warnings.size(),
                "即使降级最终失败，也必须先记下「已进入非原子路径」这条 WARNING —— "
                        + "否则运维只能看到一个 IOException，无法判断是不是文件系统不支持原子替换；实际：" + warnings);
        assertTrue(warnings.get(0).contains("ATOMIC_MOVE"), "降级 WARNING 必须点名 ATOMIC_MOVE；实际：" + warnings.get(0));
    }

    // ------------------------------------------------------------------ 3. 只有该异常才降级

    @Test
    @DisplayName("普通 IOException 不触发降级：原样上抛、不记降级 WARNING、目标不被触碰")
    void otherIoExceptionsDoNotTriggerTheFallback() throws Throwable {
        Path dir = Files.createTempDirectory("f7-no-fallback");
        Path target = dir.resolve("commands.md");
        String oldDocument = "# 旧文档\n\n普通 IO 失败时这份内容必须原样保留。\n";
        Files.writeString(target, oldDocument, StandardCharsets.UTF_8);
        Path staged = dir.resolve("commands.md.staged.tmp");
        Files.writeString(staged, "# 新文档\n", StandardCharsets.UTF_8);

        IOException injected = new IOException("注入的普通 IO 失败（不是 ATOMIC_MOVE 不受支持）");
        List<String> warnings = new ArrayList<>();
        Throwable thrown = assertThrows(Throwable.class,
                () -> invokeMoveIntoPlace(staged, target, atomicMoverThrowing(injected), warnings));

        assertEquals(injected, thrown,
                "必须是同一个异常实例原样上抛 —— 任何降级/包装都会让 generate() 的日志失真");
        assertEquals(oldDocument, Files.readString(target, StandardCharsets.UTF_8),
                "非 ATOMIC_MOVE 的失败绝不能改动目标文档");
        assertEquals(List.of(), warnings,
                "未进入降级分支就不该有降级 WARNING（否则日志会把普通 IO 故障误报成文件系统不支持原子替换）；"
                        + "实际：" + warnings);
    }

    // ------------------------------------------------------------------ 4. javadoc 诚实性

    @Test
    @DisplayName("javadoc 不再声称「任何失败都保留旧目标」，并写明降级在 Windows 上会先删目标")
    void javadocStopsClaimingTheFalseInvariant() throws Exception {
        String source = Files.readString(PRODUCTION_SOURCE, StandardCharsets.UTF_8);

        assertFalse(source.contains("任何失败都保留旧目标"),
                "javadoc 仍在承诺「任何失败都保留旧目标」—— 这在降级路径上是假的："
                        + "Windows 的非原子 Files.move 先 DeleteFile(target) 再 MoveFileEx，"
                        + "MoveFileEx 失败时旧文档已经没了（JDK sun/nio/fs/WindowsFileCopy.move）");        assertTrue(source.contains("非原子"),
                "javadoc 必须明确写出降级路径用的是非原子移动");
        assertTrue(source.contains("DeleteFile") && source.contains("先删除目标"),
                "javadoc 必须写明降级路径在 Windows 上「先删除目标、再改名」—— "
                        + "这是「旧的 commands.md 可能已经没了」的唯一原因，泛泛说「可能失败」不够");
        assertTrue(source.contains("WARNING") || source.contains("warning"),
                "javadoc 必须写明降级会记 WARNING（唯一让运维发现走了降级路径的手段）");
    }

    // ------------------------------------------------------------------ 5. 端到端：降级真的打到插件 logger

    @Test
    @DisplayName("端到端：generate() 走进降级分支时，插件 logger 里真的出现降级 WARNING，文档仍然写出")
    void generateReportsTheFallbackToThePluginLogger() throws Exception {
        MockBukkitTestBase.LogCapture capture = null;
        try {
            com.hilltopvillage.testsupport.BareHost host = loadBareHost();
            capture = attachLogCapture(host.getLogger());
            Path docFile = new File(host.getDataFolder(), "commands.md").toPath();

            Object mover = atomicMoverRejectingAtomicMove();
            // 用「参数类型是 AtomicMover」的那个包内构造器，把拒绝注入到真实调用链上。
            java.lang.reflect.Constructor<?> ctor = Arrays
                    .stream(CommandsDocumentGenerator.class.getDeclaredConstructors())
                    .filter(c -> c.getParameterCount() == 2)
                    .findFirst()
                    .orElseThrow(() -> new AssertionError(
                            "缺少「插件 + AtomicMover」的包内构造器：降级 WARNING 无法端到端验证"));
            ctor.setAccessible(true);
            CommandsDocumentGenerator generator =
                    (CommandsDocumentGenerator) ctor.newInstance(host, mover);
            generator.generate();

            long deadline = System.nanoTime() + 10_000L * 1_000_000L;
            // 等的是「成功那条 INFO」而不是 WARNING：降级 WARNING 在非原子移动**之前**发出，
            // 只等它会把「移动还没做完」当成「已结束」，从而读到尚未落盘的文件。
            while (System.nanoTime() < deadline && !capture.anyContains("Command reference generated")) {
                Thread.sleep(25L);
            }

            assertTrue(capture.anyMatch(line -> line.startsWith("WARNING|") && line.contains("ATOMIC_MOVE")),
                    "降级分支必须把 WARNING 打到插件 logger（运维唯一能发现「文件系统不支持原子替换」的渠道）；"
                            + "实际日志：" + capture.lines());
            assertEquals(0, capture.countAt(java.util.logging.Level.SEVERE),
                    "降级是可恢复的文档产物问题，不该是 SEVERE；实际日志：" + capture.lines());
            assertTrue(capture.anyContains("Command reference generated"),
                    "降级成功后仍应打出「已生成」的 INFO（降级不是失败）；实际日志：" + capture.lines());
            assertTrue(Files.isRegularFile(docFile),
                    "降级路径成功后 commands.md 仍必须存在（走到非原子移动就该把它搬到位）；"
                            + "目录内容：" + listNames(docFile.getParent()));
        } finally {
            if (capture != null) {
                detachLogCapture();
            }
        }
    }

    // ------------------------------------------------------------------ 反射工具

    private static List<String> listNames(Path dir) {
        try (var stream = Files.list(dir)) {
            return stream.map(path -> path.getFileName().toString()).sorted().toList();
        } catch (IOException unreadable) {
            return List.of("<unreadable: " + unreadable + ">");
        }
    }

    /**
     * 调用 {@code moveIntoPlace(Path, Path, AtomicMover, Consumer<String>)}。
     *
     * <p>用反射而不是直接调用：修复前该方法不存在，反射能让失败表现为清晰的
     * {@link AssertionError}（「降级逻辑不可单独测试」），而不是一个编译错误。</p>
     */
    private static void invokeMoveIntoPlace(Path source, Path target, Object atomicMover,
            List<String> warnings) throws Throwable {
        Method moveIntoPlace = findMoveIntoPlace();
        try {
            moveIntoPlace.invoke(null, source, target, atomicMover, (Consumer<String>) warnings::add);
        } catch (InvocationTargetException invocation) {
            throw invocation.getCause();
        }
    }

    private static Method findMoveIntoPlace() {
        Method found = Arrays.stream(CommandsDocumentGenerator.class.getDeclaredMethods())
                .filter(method -> method.getName().equals("moveIntoPlace"))
                .filter(method -> method.getParameterCount() == 4)
                .filter(method -> method.getParameterTypes()[0] == Path.class)
                .findFirst()
                .orElse(null);
        assertNotNull(found,
                "CommandsDocumentGenerator 缺少可单独调用的 moveIntoPlace(Path, Path, AtomicMover, Consumer)："
                        + "降级分支必须成为可被真实执行的生产代码（缺陷 2：现有测试只替换整个 MoveStep 接缝，"
                        + "moveIntoPlace 从未被执行过）");
        found.setAccessible(true);
        Class<?> moverType = found.getParameterTypes()[2];
        assertTrue(moverType.isInterface(),
                "第 3 参数应为可注入的「原子移动」函数式接口，实际是 " + moverType.getName());
        return found;
    }

    /** 注入物：只把控制流推进 catch 分支，不做任何文件操作。 */
    private static Object atomicMoverRejectingAtomicMove() throws Exception {
        Method moveIntoPlace = findMoveIntoPlace();
        Class<?> moverType = moveIntoPlace.getParameterTypes()[2];
        InvocationHandler handler = (proxy, method, args) -> {
            if (method.getDeclaringClass() == Object.class) {
                return switch (method.getName()) {
                    case "toString" -> "atomic-mover-rejecting-atomic-move";
                    case "hashCode" -> System.identityHashCode(proxy);
                    case "equals" -> proxy == args[0];
                    default -> null;
                };
            }
            Path source = (Path) args[0];
            Path destination = (Path) args[1];
            throw new AtomicMoveNotSupportedException(
                    source.toString(), destination.toString(), "注入：本文件系统不支持原子替换（F7 降级路径）");
        };
        return Proxy.newProxyInstance(CommandsDocumentGenerator.class.getClassLoader(),
                new Class<?>[] {moverType}, handler);
    }

    /** 注入物：抛一个不是 {@link AtomicMoveNotSupportedException} 的普通 IO 失败。 */
    private static Object atomicMoverThrowing(IOException failure) throws Exception {
        Method moveIntoPlace = findMoveIntoPlace();
        Class<?> moverType = moveIntoPlace.getParameterTypes()[2];
        InvocationHandler handler = (proxy, method, args) -> {
            if (method.getDeclaringClass() == Object.class) {
                return switch (method.getName()) {
                    case "toString" -> "atomic-mover-throwing-io";
                    case "hashCode" -> System.identityHashCode(proxy);
                    case "equals" -> proxy == args[0];
                    default -> null;
                };
            }
            throw failure;
        };
        return Proxy.newProxyInstance(CommandsDocumentGenerator.class.getClassLoader(),
                new Class<?>[] {moverType}, handler);
    }
}

package com.hilltopvillage.doc;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import com.hilltopvillage.testsupport.BareHost;
import com.hilltopvillage.testsupport.MockBukkitTestBase;

/**
 * 生成文档与 {@code /hilltop tps} 实际输出的一致性测试。
 *
 * <p>{@code TpsDiagnostic#printDiagnostic} 只输出 TPS/MSPT、内存、玩家、波次、怪物、节点
 * 与各世界实体/区块计数，不存在 DisplayEntity 清理队列；{@code DisplayEntityManager}
 * 的类注释也明确说明该清理队列链已作为零调用死代码删除。因此自动生成的命令参考
 * 不得再向管理员承诺这个不存在的输出项。</p>
 */
@DisplayName("CommandsDocumentGenerator — /hilltop tps 不得记录已删除的清理队列")
class CommandsDocumentationCleanupClaimTest extends MockBukkitTestBase {

    private static final long ASYNC_TIMEOUT_MILLIS = 10_000L;

    @Test
    @DisplayName("生成的 /hilltop tps 文档不得包含 DisplayEntity 清理队列")
    void generatedTpsDocumentationDoesNotClaimDisplayEntityCleanupQueue() throws Exception {
        BareHost host = loadBareHost();
        File docFile = new File(host.getDataFolder(), "commands.md");

        new CommandsDocumentGenerator(host).generate();
        String content = awaitDocument(docFile);

        assertTrue(content.contains("### `/hilltop tps`"),
                "前置条件：生成的文档必须包含 /hilltop tps 段，否则本测试没有瞄准目标段落");
        assertFalse(content.contains("DisplayEntity 清理队列"),
                "生成的 /hilltop tps 文档仍声称输出「DisplayEntity 清理队列」，但 "
                        + "TpsDiagnostic#printDiagnostic 不输出该项，DisplayEntityManager "
                        + "也注明该清理队列链已删除。管理员会据此排查不存在的输出。");
    }

    /** 等待异步写盘完成并读取全文；长度连续稳定后才读取，避免读到半份文件。 */
    private String awaitDocument(File file) throws Exception {
        long deadline = System.nanoTime() + ASYNC_TIMEOUT_MILLIS * 1_000_000L;
        long lastLength = -1L;
        int stableSamples = 0;
        while (System.nanoTime() < deadline) {
            long length = file.isFile() ? file.length() : -1L;
            if (length > 0 && length == lastLength) {
                if (++stableSamples >= 3) {
                    break;
                }
            } else {
                stableSamples = 0;
            }
            lastLength = length;
            Thread.sleep(25L);
        }

        assertTrue(file.isFile() && file.length() > 0,
                "异步写盘未在 " + ASYNC_TIMEOUT_MILLIS + "ms 内产生非空 commands.md");
        return Files.readString(file.toPath(), StandardCharsets.UTF_8);
    }
}

package com.hilltopvillage.mechanics;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyDouble;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.io.File;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicReference;

import org.bukkit.Material;
import org.bukkit.World;
import org.bukkit.block.Block;
import org.bukkit.block.BlockFace;
import org.bukkit.entity.Player;
import org.bukkit.event.block.Action;
import org.bukkit.event.player.PlayerInteractEvent;
import org.bukkit.inventory.EquipmentSlot;
import org.bukkit.inventory.ItemStack;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import com.hilltopvillage.HilltopVillagePlugin;
import com.hilltopvillage.arena.ArenaInstance;
import com.hilltopvillage.arena.MultiArenaManager;
import com.hilltopvillage.config.GameConfig;
import com.hilltopvillage.core.GameManager;
import com.hilltopvillage.core.PlayerData;
import com.hilltopvillage.mechanics.NodeSystem.NodeData;
import com.hilltopvillage.testsupport.MockBukkitTestBase;
import com.hilltopvillage.util.DisplayEntityManager;

/**
 * #1 修复结算：{@code repair-cost-amount} 是「最多消耗几个物品」，不是「每次固定扣几个」，
 * 且恢复量必须按实际消耗的物品数计算。
 *
 * <p>本类走真实 {@link NodeListener#onPlayerInteract}，只把节点系统/竞技场查表替换为 mock，
 * 因此红色失败对应的是生产结算代码本身，而不是测试里复制的一份算术。</p>
 *
 * <p>四种缺陷形态：cost=5 少恢复、cost=0 免费、cost&lt;0 物品反增、
 * 节点只差 30 血仍扣 5 个。第五种（持有不足）确保不会凭配置值透支。</p>
 */
class RepairSettlementTest extends MockBukkitTestBase {

    private World world;
    private Player player;
    private NodeListener listener;
    private GameConfig config;
    private NodeData node;
    private final AtomicReference<Double> restored = new AtomicReference<>(0.0);

    @BeforeEach
    void setUp() {
        config = new GameConfig();
        HilltopVillagePlugin plugin = MechanicsFixtures.mockPlugin(
                java.util.logging.Logger.getLogger("repair-settlement-" + System.nanoTime()),
                new File(dataFolder.toFile(), "plugin"), config);

        world = server.addSimpleWorld("repair_settlement_world");
        player = server.addPlayer("Repairer");

        ArenaInstance arena = mock(ArenaInstance.class);
        GameManager gameManager = mock(GameManager.class);
        MultiArenaManager arenaManager = mock(MultiArenaManager.class);
        NodeSystem nodeSystem = mock(NodeSystem.class);
        node = mock(NodeData.class);
        DisplayEntityManager display = mock(DisplayEntityManager.class);

        when(arena.getGameManager()).thenReturn(gameManager);
        when(arenaManager.getArenaByWorld(world.getName())).thenReturn(arena);
        when(plugin.getMultiArenaManager()).thenReturn(arenaManager);

        when(gameManager.isGameRunning()).thenReturn(true);
        when(gameManager.isSettlementPhase()).thenReturn(false);
        when(gameManager.getNodeSystem()).thenReturn(nodeSystem);
        when(gameManager.getPlayerData(any(Player.class)))
                .thenReturn(new PlayerData(UUID.randomUUID()));
        when(gameManager.getDisplayEntityManager()).thenReturn(display);

        when(nodeSystem.isNodeBlock(any(Block.class))).thenReturn(true);
        when(nodeSystem.getNodeAt(any())).thenReturn(node);
        when(nodeSystem.isNodeFull(node)).thenReturn(false);
        when(nodeSystem.repairNode(any(), any(Player.class), anyDouble())).thenAnswer(invocation -> {
            restored.set(invocation.getArgument(2));
            return true;
        });

        listener = new NodeListener(plugin);
    }

    private record Outcome(int remainingItems, double restoredHealth) {
    }

    private Outcome clickWith(int cost, double perItem, int held, double currentHealth,
            double maxHealth) {
        config.setRepairCostAmount(cost);
        config.setRepairAmountPerCost(perItem);
        when(node.getCurrentHealth()).thenReturn(currentHealth);
        when(node.getMaxHealth()).thenReturn(maxHealth);
        restored.set(0.0);

        ItemStack repairItem = listener.createRepairItem(held);
        assertEquals(held, repairItem.getAmount(), "前置条件：工厂必须真的给足持有量");
        player.getInventory().setItemInMainHand(repairItem);
        assertEquals(held, player.getInventory().getItemInMainHand().getAmount(),
                "前置条件：主手必须保留全部持有量");
        Block clicked = world.getBlockAt(8, 64, 8);
        clicked.setType(Material.RESPAWN_ANCHOR);
        PlayerInteractEvent event = new PlayerInteractEvent(
                player, Action.RIGHT_CLICK_BLOCK, repairItem, clicked,
                BlockFace.NORTH, EquipmentSlot.HAND);
        listener.onPlayerInteract(event);

        ItemStack after = player.getInventory().getItemInMainHand();
        int remaining = after == null || after.getType().isAir() ? 0 : after.getAmount();
        return new Outcome(remaining, restored.get());
    }

    @Test
    @DisplayName("cost=5、节点只差 30 血：只消耗 1 个，恢复 30（不白扣另外 4 个）")
    void consumesOnlyWhatTheDeficitNeeds() {
        Outcome outcome = clickWith(5, 50.0, 10, 170.0, 200.0);

        assertEquals(9, outcome.remainingItems(),
                "差 30 血只需 ceil(30/50)=1 个物品；固定扣 5 个会让玩家白丢 4 个");
        assertEquals(30.0, outcome.restoredHealth(), 1e-9,
                "恢复量必须等于实际缺口，不能按「每物品恢复量」写死 50");
    }

    @Test
    @DisplayName("cost=5、缺口 250：消耗 5 个并恢复 5×50=250（不是只恢复 50）")
    void consumesConfiguredCostAndRestoresAllOfIt() {
        Outcome outcome = clickWith(5, 50.0, 10, 0.0, 250.0);

        assertEquals(5, 10 - outcome.remainingItems(),
                "缺口 250 / 每物品 50 需要 5 个，且不超过配置上限");
        assertEquals(250.0, outcome.restoredHealth(), 1e-9,
                "★ 消耗 5 个只恢复 1 份是 #1 的核心缺陷");
    }

    @Test
    @DisplayName("cost=0：不消耗也不修复（免费修复必须被拒绝）")
    void zeroCostDoesNothing() {
        Outcome outcome = clickWith(0, 50.0, 10, 0.0, 100.0);

        assertEquals(10, outcome.remainingItems(), "cost=0 不得消耗物品");
        assertEquals(0.0, outcome.restoredHealth(), 1e-9,
                "cost=0 不得凭空修复；#7 会把载入值钳到 1，纯函数仍需防御编程赋值");
    }

    @Test
    @DisplayName("cost=-3：不消耗也不修复（负数不得让物品反增）")
    void negativeCostDoesNothing() {
        Outcome outcome = clickWith(-3, 50.0, 10, 0.0, 100.0);

        assertEquals(10, outcome.remainingItems(), "负数 cost 不得把物品从 10 加到 13");
        assertEquals(0.0, outcome.restoredHealth(), 1e-9, "负数 cost 不得修复");
    }

    @Test
    @DisplayName("持有不足：cost=5 但只有 2 个 → 消耗 2 个、恢复 100，不透支")
    void neverConsumesMoreThanHeld() {
        Outcome outcome = clickWith(5, 50.0, 2, 0.0, 250.0);

        assertEquals(100.0, outcome.restoredHealth(), 1e-9,
                "恢复量必须按实际消耗的 2 个计算，而不是配置的 5 个");
        assertEquals(0, outcome.remainingItems(), "只能消耗实际持有的 2 个");
    }
}

package com.hilltopvillage.shop;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.io.IOException;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import com.hilltopvillage.testsupport.BareHost;
import com.hilltopvillage.testsupport.MockBukkitTestBase;

/**
 * F4 regression: an explicit non-positive {@code amount} must not become a billable item.
 *
 * <p>{@link ShopConfigLoader#parseItem} reads {@code getInt(path + ".amount", 1)},
 * so {@code amount: 0} and {@code amount: -5} are accepted into {@link ShopItem}.
 * {@code ShopManager#deliverItem} later clamps the delivered stack to one, while the
 * purchase still charges the configured price. The loader must skip such an item and
 * warn with the invalid value, while a missing or null amount keeps the existing
 * default of 1 and an explicit positive amount is honored.</p>
 */
class ShopConfigAmountValidationTest extends MockBukkitTestBase {

    private BareHost host;
    private ShopConfigLoader loader;

    @BeforeEach
    void setUp() {
        host = loadBareHost();
        loader = new ShopConfigLoader(host);
    }

    /** 把给定 YAML 写进宿主数据目录，再走一次真实的 {@link ShopConfigLoader#load()}。 */
    private ShopConfig load(String yaml) throws IOException {
        TestPaths.write(new File(host.getDataFolder(), "shop.yml"), yaml);
        return loader.load();
    }

    private static ShopItem byId(ShopConfig config, String id) {
        Map<String, ShopItem> byId = config.getItems().stream()
                .collect(Collectors.toMap(ShopItem::getId, Function.identity()));
        return byId.get(id);
    }

    /** 一个只有单件商品的极简配置骨架，便于逐条替换其中的某一键。 */
    private static String singleItem(String itemBody) {
        return """
                shop:
                  currency:
                    material: EMERALD
                  gui:
                    size: 54
                  items:
                    probe:
                """ + itemBody.lines()
                .map(line -> "      " + line)
                .collect(Collectors.joining("\n")) + "\n";
    }

    @Test
    @DisplayName("F4: amount: 0 被跳过并告警，不进入 ShopConfig")
    void zeroAmountIsSkipped() throws IOException {
        LogCapture logs = attachLogCapture(host.getLogger());
        ShopConfig config = load(singleItem("""
                slot: 0
                price: 10
                amount: 0
                type: MATERIAL
                icon:
                  material: BOW
                """));

        ShopItem probe = byId(config, "probe");
        assertNull(probe,
                () -> "An explicit amount: 0 must reject the item instead of delivering a"
                        + " clamped stack while charging the full price; it loaded with amount "
                        + probe.getAmount() + " (items: "
                        + config.getItems().stream().map(ShopItem::getId).toList() + ")");
        assertTrue(logs.anyContains("invalid amount 0"),
                "The skip must warn with the invalid value so the owner can fix shop.yml: "
                        + logs.lines());
        assertTrue(logs.anyContains("item 'probe'"),
                "The warning must name the offending item: " + logs.lines());
    }

    @Test
    @DisplayName("F4: 负 amount 被跳过并告警，不进入 ShopConfig")
    void negativeAmountIsSkipped() throws IOException {
        LogCapture logs = attachLogCapture(host.getLogger());
        ShopConfig config = load(singleItem("""
                slot: 0
                price: 10
                amount: -5
                type: MATERIAL
                icon:
                  material: BOW
                """));

        ShopItem probe = byId(config, "probe");
        assertNull(probe,
                () -> "An explicit amount: -5 must reject the item instead of delivering a"
                        + " clamped stack while charging the full price; it loaded with amount "
                        + probe.getAmount() + " (items: "
                        + config.getItems().stream().map(ShopItem::getId).toList() + ")");
        assertTrue(logs.anyContains("invalid amount -5"),
                "The skip must warn with the invalid value so the owner can fix shop.yml: "
                        + logs.lines());
        assertTrue(logs.anyContains("item 'probe'"),
                "The warning must name the offending item: " + logs.lines());
    }

    @Test
    @DisplayName("F4 控制组: 缺 amount 键仍按既有默认值 1 加载")
    void missingAmountDefaultsToOne() throws IOException {
        LogCapture logs = attachLogCapture(host.getLogger());
        ShopConfig config = load(singleItem("""
                slot: 0
                price: 10
                type: MATERIAL
                icon:
                  material: BOW
                """));

        ShopItem probe = byId(config, "probe");
        assertNotNull(probe,
                "A missing amount key must keep the existing default of 1 (items: "
                        + config.getItems().stream().map(ShopItem::getId).toList() + ")");
        assertEquals(1, probe.getAmount(),
                "A missing amount key must not be treated as an invalid explicit amount");
        assertFalse(logs.anyContains("invalid amount"),
                "A missing amount is valid and must not produce an invalid-amount warning: "
                        + logs.lines());
    }

    @Test
    @DisplayName("F4 控制组: amount: null 仍按既有默认值 1 加载")
    void nullAmountDefaultsToOne() throws IOException {
        LogCapture logs = attachLogCapture(host.getLogger());
        ShopConfig config = load(singleItem("""
                slot: 0
                price: 10
                amount:
                type: MATERIAL
                icon:
                  material: BOW
                """));

        ShopItem probe = byId(config, "probe");
        assertNotNull(probe,
                "An explicit amount: null must keep the existing default of 1 (items: "
                        + config.getItems().stream().map(ShopItem::getId).toList() + ")");
        assertEquals(1, probe.getAmount(),
                "An explicit amount: null must not be treated as an invalid explicit amount");
        assertFalse(logs.anyContains("invalid amount"),
                "amount: null is valid and must not produce an invalid-amount warning: "
                        + logs.lines());
    }

    @Test
    @DisplayName("F4 控制组: amount: 3 仍原样加载为 3")
    void positiveAmountIsHonored() throws IOException {
        LogCapture logs = attachLogCapture(host.getLogger());
        ShopConfig config = load(singleItem("""
                slot: 0
                price: 10
                amount: 3
                type: MATERIAL
                icon:
                  material: BOW
                """));

        ShopItem probe = byId(config, "probe");
        assertNotNull(probe,
                "A positive explicit amount must still load (items: "
                        + config.getItems().stream().map(ShopItem::getId).toList() + ")");
        assertEquals(3, probe.getAmount(),
                "A positive explicit amount must be honored verbatim");
        assertFalse(logs.anyContains("invalid amount"),
                "A valid amount must not produce an invalid-amount warning: " + logs.lines());
    }

    @Test
    @DisplayName("F4: 被 amount 校验跳过的条目不得占用槽位，后续同槽商品不报冲突")
    void invalidAmountDoesNotReserveSlotForFollowingItem() throws IOException {
        LogCapture logs = attachLogCapture(host.getLogger());
        ShopConfig config = load("""
                shop:
                  currency:
                    material: EMERALD
                  gui:
                    size: 54
                  items:
                    bad:
                      slot: 3
                      price: 10
                      amount: 0
                      type: MATERIAL
                      icon:
                        material: BOW
                    good:
                      slot: 3
                      price: 10
                      amount: 3
                      type: MATERIAL
                      icon:
                        material: DIAMOND
                """);

        ShopItem bad = byId(config, "bad");
        ShopItem good = byId(config, "good");
        assertNull(bad,
                () -> "amount: 0 must still reject the bad item; it loaded with amount "
                        + bad.getAmount() + " (items: "
                        + config.getItems().stream().map(ShopItem::getId).toList() + ")");
        assertNotNull(good,
                "The valid same-slot item must still load after the invalid entry is skipped"
                        + " (items: " + config.getItems().stream().map(ShopItem::getId).toList() + ")");
        assertEquals(3, good.getSlot(),
                "The positive control must occupy the same slot as the skipped item");
        assertEquals(3, good.getAmount(),
                "The valid item's positive amount must be honored");
        assertTrue(logs.anyContains("invalid amount 0"),
                "The invalid item must still be reported with its value: " + logs.lines());
        assertFalse(logs.anyContains("conflicts with item 'bad'"),
                "A skipped invalid item must not reserve its slot and create a false conflict"
                        + " warning for the following valid item: " + logs.lines());
    }
}

package com.hilltopvillage.shop;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.io.IOException;

import org.bukkit.Material;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import com.hilltopvillage.testsupport.BareHost;
import com.hilltopvillage.testsupport.MockBukkitTestBase;

/**
 * F1 regression: an unparseable or parseable-truncated {@code shop.yml} must not become a valid empty shop.
 *
 * <p>{@code YamlConfiguration.loadConfiguration(File)} logs and swallows parse errors, returning an
 * empty configuration. Before the fix, {@link ShopConfigLoader#load()} therefore returned a normal
 * {@link ShopConfig} with no items, silently replacing a working shop after {@code /hilltop shop reload}.
 * A truncation can also be syntactically valid: if it ends at the {@code items:} header, Bukkit drops
 * the null value and the key looks omitted. Both forms must fail visibly, and
 * {@link ShopManager#reload()} must leave the previous snapshot untouched when that failure escapes.</p>
 */
class ShopConfigCorruptFileTest extends MockBukkitTestBase {

    /** YAML with an unclosed flow sequence: SnakeYAML must reject this, not parse it as empty. */
    private static final String CORRUPT_SHOP_YML = """
            shop:
              items:
                broken: [unclosed
            """;

    /**
     * Parseable truncation: the {@code items:} key still exists, but its value is null.
     * This is what a write cut off at the end of the items header produces.
     */
    private static final String TRUNCATED_AT_ITEMS = """
            shop:
              currency:
                material: EMERALD
              npc:
                name: "&aShop Keeper"
              gui:
                size: 54
              items:
            """;

    private BareHost host;
    private ShopConfigLoader loader;
    private File shopFile;

    @BeforeEach
    void setUp() {
        host = loadBareHost();
        loader = new ShopConfigLoader(host);
        shopFile = new File(host.getDataFolder(), "shop.yml");
    }

    @Test
    @DisplayName("F1: invalid shop.yml throws a descriptive failure instead of returning an empty ShopConfig")
    void corruptFileDoesNotReturnEmptyShop() throws IOException {
        TestPaths.write(shopFile, CORRUPT_SHOP_YML);

        IllegalStateException failure = assertThrows(IllegalStateException.class, loader::load,
                "A corrupt shop.yml must fail visibly; returning an empty ShopConfig silently replaces "
                        + "a working shop with nothing");

        String message = failure.getMessage();
        assertNotNull(message, "The parse failure must carry a diagnostic message");
        assertTrue(message.contains("shop.yml"),
                "The failure must identify the offending file so the admin can act on it: " + message);
    }

    @Test
    @DisplayName("F1: failed reload keeps the last valid ShopConfig snapshot")
    void corruptReloadKeepsPreviousConfig() throws IOException {
        TestPaths.write(shopFile, """
                shop:
                  currency:
                    material: DIAMOND
                  gui:
                    size: 27
                  items: {}
                """);
        ShopManager shop = new ShopManager(host);
        shop.reload();
        ShopConfig previous = shop.getShopConfig();

        TestPaths.write(shopFile, CORRUPT_SHOP_YML);

        assertThrows(IllegalStateException.class, shop::reload,
                "Reloading a corrupt shop.yml must fail instead of replacing the live shop with an empty one");
        assertSame(previous, shop.getShopConfig(),
                "A failed load must not assign a new empty config; the last valid snapshot must survive");
        assertSame(Material.DIAMOND, shop.getShopConfig().getCurrencyMaterial(),
                "The preserved snapshot must still be the previously loaded one");
    }

    @Test
    @DisplayName("F1: parseable truncation at the items: header fails and preserves the last snapshot")
    void truncatedItemsHeaderFailsAndPreservesPreviousConfig() throws IOException {
        TestPaths.write(shopFile, """
                shop:
                  currency:
                    material: DIAMOND
                  gui:
                    size: 54
                  items:
                    probe:
                      slot: 0
                      price: 1
                      type: MATERIAL
                      icon:
                        material: BOW
                """);
        ShopManager shop = new ShopManager(host);
        shop.reload();
        ShopConfig previous = shop.getShopConfig();
        assertEquals(1, previous.getItems().size(),
                "The fixture must begin with one valid item so replacement is observable");

        TestPaths.write(shopFile, TRUNCATED_AT_ITEMS);

        IllegalStateException directFailure = assertThrows(IllegalStateException.class, loader::load,
                "A present-but-null shop.items key is a parseable truncation and must not load as empty");
        assertNotNull(directFailure.getMessage(), "The truncated items failure must be descriptive");
        assertTrue(directFailure.getMessage().contains("shop.yml"), directFailure.getMessage());
        assertTrue(directFailure.getMessage().contains("shop.items"), directFailure.getMessage());

        assertThrows(IllegalStateException.class, shop::reload,
                "Reloading the truncated shop.yml must fail instead of replacing the live shop");
        assertSame(previous, shop.getShopConfig(),
                "The previous snapshot must survive when the items header is truncated");
        assertEquals(1, shop.getShopConfig().getItems().size(),
                "The preserved snapshot must still contain its original item");
    }

    @Test
    @DisplayName("F1: explicit empty items mapping and omitted items remain valid")
    void emptyOrOmittedItemsRemainValid() throws IOException {
        TestPaths.write(shopFile, """
                shop:
                  gui:
                    size: 27
                  items: {}
                """);
        assertTrue(loader.load().getItems().isEmpty(),
                "An explicit empty mapping is a legitimate empty shop");

        TestPaths.write(shopFile, """
                shop:
                  gui:
                    size: 27
                """);
        assertTrue(loader.load().getItems().isEmpty(),
                "Omitting items keeps the existing empty-item behavior");
    }
}

package com.hilltopvillage.shop;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.io.IOException;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;

import org.bukkit.Material;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import com.hilltopvillage.testsupport.BareHost;
import com.hilltopvillage.testsupport.MockBukkitTestBase;

/**
 * F2 regression: a {@code MATERIAL} item must not silently fall back to a
 * {@link Material#BARRIER} icon when {@code icon.material} is omitted.
 *
 * <p>{@link ShopConfigLoader#parseItem} initializes {@code icon} to {@code BARRIER} and only
 * rejected a missing {@code icon.material} for {@code EQUIPMENT}. For {@code MATERIAL}, the
 * GUI/delivery icon is built from that same field, so an omitted key silently shipped a barrier
 * block instead of the configured item. The loader must skip such an entry just as it does for
 * {@code EQUIPMENT}, while still honoring a valid {@code MATERIAL} icon.</p>
 */
class ShopConfigMaterialValidationTest extends MockBukkitTestBase {

    private BareHost host;
    private ShopConfigLoader loader;

    @BeforeEach
    void setUp() {
        host = loadBareHost();
        loader = new ShopConfigLoader(host);
    }

    @Test
    @DisplayName("F2 契约回归: MATERIAL 缺 icon.material 保留商品并回落 BARRIER，但有告警")
    void materialWithoutIconKeepsBarrierFallbackButWarns() throws IOException {
        LogCapture logs = attachLogCapture(host.getLogger());
        TestPaths.write(new File(host.getDataFolder(), "shop.yml"), """
                shop:
                  currency:
                    material: EMERALD
                  gui:
                    size: 54
                  items:
                    no_icon:
                      slot: 0
                      price: 1
                      type: MATERIAL
                    with_icon:
                      slot: 1
                      price: 1
                      type: MATERIAL
                      icon:
                        material: DIAMOND_SWORD
                """);

        ShopConfig config = loader.load();
        Map<String, ShopItem> byId = config.getItems().stream()
                .collect(Collectors.toMap(ShopItem::getId, Function.identity()));
        ShopItem missingIcon = byId.get("no_icon");
        ShopItem validIcon = byId.get("with_icon");

        assertAll("F2 MATERIAL icon validation",
                () -> {
                    assertNotNull(missingIcon,
                            "Dropping the item is destructive: the GUI silently loses a slot"
                                    + " and the owner only sees one warning line (items: "
                                    + byId.keySet() + ")");
                    assertEquals(Material.BARRIER, missingIcon.getIcon(),
                            "The pre-existing contract is the visible BARRIER fallback icon,"
                                    + " not a vanished slot");
                },
                () -> {
                    assertNotNull(validIcon,
                            "Positive control: a MATERIAL item with icon.material: DIAMOND_SWORD must"
                                    + " still load (items: " + byId.keySet() + ")");
                    assertEquals("MATERIAL", validIcon.getType(),
                            "The positive control must remain a MATERIAL item");
                    assertEquals(Material.DIAMOND_SWORD, validIcon.getIcon(),
                            "The configured icon must be honored instead of the BARRIER default");
                },
                () -> assertTrue(logs.anyContains("MATERIAL item 'no_icon'"),
                        "Keeping the item must still be observable: the pre-fix code was silent,"
                                + " and silence is the defect F2 should have fixed: " + logs.lines()));
    }
}

package com.hilltopvillage.shop;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.io.IOException;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import com.hilltopvillage.testsupport.BareHost;
import com.hilltopvillage.testsupport.MockBukkitTestBase;

/**
 * F3 regression: a missing {@code price} key must not be silently priced at 1.
 *
 * <p>{@link ShopConfigLoader#parseItem} reads {@code getInt(path + ".price", 1)}, so an item
 * whose owner forgot {@code price} and an explicit {@code price: 0} are indistinguishable in
 * the result: the former silently becomes a 1-currency item with no diagnostic. The loader must
 * reject/skip an item whose price key is absent or null, while {@code price: 0} stays a valid
 * intentional free item and negative prices keep their existing clamp-to-0 warning.</p>
 */
class ShopConfigPriceValidationTest extends MockBukkitTestBase {

    private BareHost host;
    private ShopConfigLoader loader;

    @BeforeEach
    void setUp() {
        host = loadBareHost();
        loader = new ShopConfigLoader(host);
    }

    /** 把给定 YAML 写进宿主数据目录，再走一次真实的 {@link ShopConfigLoader#load()}。 */
    private ShopConfig load(String yaml) throws IOException {
        TestPaths.write(new File(host.getDataFolder(), "shop.yml"), yaml);
        return loader.load();
    }

    private static ShopItem byId(ShopConfig config, String id) {
        Map<String, ShopItem> byId = config.getItems().stream()
                .collect(Collectors.toMap(ShopItem::getId, Function.identity()));
        return byId.get(id);
    }

    /** 一个只有单件商品的极简配置骨架，便于逐条替换其中的某一键。 */
    private static String singleItem(String itemBody) {
        return """
                shop:
                  currency:
                    material: EMERALD
                  gui:
                    size: 54
                  items:
                    probe:
                """ + itemBody.lines()
                .map(line -> "      " + line)
                .collect(Collectors.joining("\n")) + "\n";
    }

    @Test
    @DisplayName("F3 契约回归: 缺 price 键仍按默认 1 加载，但必须告警")
    void missingPriceKeyDefaultsToOneWithWarning() throws IOException {
        LogCapture logs = attachLogCapture(host.getLogger());
        ShopConfig config = load(singleItem("""
                slot: 0
                type: MATERIAL
                icon:
                  material: BOW
                """));

        ShopItem probe = byId(config, "probe");
        assertNotNull(probe,
                "A missing price key is a legal configuration: getInt(..., 1) defaults to 1."
                        + " It must load, not be rejected (items: "
                        + config.getItems().stream().map(ShopItem::getId).toList() + ")");
        assertEquals(1, probe.getPrice(),
                "A missing price key must keep the documented default of 1");
        assertTrue(logs.anyContains("missing price"),
                "The warning about the implicit default is the actual F3 fix: "
                        + logs.lines());
        assertTrue(logs.anyContains("item 'probe'"),
                "The warning must name the offending item: " + logs.lines());
        assertTrue(logs.anyContains("defaulting to 1"),
                "The warning must name the default actually applied: " + logs.lines());
    }

    @Test
    @DisplayName("F3 契约回归: 显式 price: null 同样按默认 1 加载，但必须告警")
    void nullPriceDefaultsToOneWithWarning() throws IOException {
        LogCapture logs = attachLogCapture(host.getLogger());
        ShopConfig config = load(singleItem("""
                slot: 0
                price:
                type: MATERIAL
                icon:
                  material: BOW
                """));

        ShopItem probe = byId(config, "probe");
        assertNotNull(probe,
                "An explicit price: null reads as an unset key, so it must keep the default"
                        + " of 1 and load (items: "
                        + config.getItems().stream().map(ShopItem::getId).toList() + ")");
        assertEquals(1, probe.getPrice(),
                "A null price key must keep the documented default of 1");
        assertTrue(logs.anyContains("missing price"),
                "The warning must still fire for a null price: " + logs.lines());
        assertTrue(logs.anyContains("item 'probe'"),
                "The warning must name the offending item: " + logs.lines());
    }

    @Test
    @DisplayName("F3 控制组: price: 0 仍合法加载为免费，且不报缺价/负价告警")
    void zeroPriceIsLegalWithoutWarning() throws IOException {
        LogCapture logs = attachLogCapture(host.getLogger());
        ShopConfig config = load(singleItem("""
                slot: 0
                price: 0
                type: MATERIAL
                icon:
                  material: BOW
                """));

        ShopItem probe = byId(config, "probe");
        assertNotNull(probe,
                "price: 0 is an intentional free item and must still load (items: "
                        + config.getItems().stream().map(ShopItem::getId).toList() + ")");
        assertEquals(0, probe.getPrice(),
                "An explicit 0 must be honored as free, not replaced by a default");
        assertFalse(logs.anyContains("missing price"),
                "A present price: 0 must not be reported as missing: " + logs.lines());
        assertFalse(logs.anyContains("negative price"),
                "0 is not negative and must not trigger the clamp warning: " + logs.lines());
    }

    @Test
    @DisplayName("F3 控制组: price: -5 仍钳到 0 并保留负价格告警")
    void negativePriceIsStillClampedToZero() throws IOException {
        LogCapture logs = attachLogCapture(host.getLogger());
        ShopConfig config = load(singleItem("""
                slot: 0
                price: -5
                type: MATERIAL
                icon:
                  material: BOW
                """));

        ShopItem probe = byId(config, "probe");
        assertNotNull(probe,
                "Negative price is a misconfiguration, not an invalid item; it stays loaded"
                        + " (items: " + config.getItems().stream().map(ShopItem::getId).toList() + ")");
        assertEquals(0, probe.getPrice(),
                "Negative prices must still clamp to 0 so removeCurrency cannot give the item away");
        assertTrue(logs.anyContains("negative price -5"),
                "The existing clamp warning must survive the F3 change: " + logs.lines());
    }
}

package com.hilltopvillage.shop;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.io.IOException;

import org.bukkit.Material;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import com.hilltopvillage.testsupport.BareHost;
import com.hilltopvillage.testsupport.MockBukkitTestBase;

/**
 * F1 的修复（{@code !loaded.usable()} 时抛 {@link IllegalStateException}）引入的回归：
 * {@link ShopConfigLoader#load()} 第一行对「文件不存在」无条件 {@code saveResource}，
 * 而 {@code YamlFiles.load} 在隔离坏文件时已经把它改名成 {@code shop.yml.corrupt}。
 * 于是「被隔离」与「首次安装」在文件系统层面完全一样 —— 下一次 {@code load()}
 * （同一进程内再 reload，或重启后的首个 load）会静默写回出厂模板，
 * 把服主的商品 / 价格 / currency.name / npc.name / gui.title 全部覆盖。
 *
 * <p>本类钉住三件事，缺一不可：</p>
 * <ol>
 *   <li><b>被隔离后不得重建</b>（同进程第二次 load、以及「重启」＝新 loader 实例）；</li>
 *   <li><b>首次安装仍必须生成模板</b>（防「修过头」把正常路径也打死）；</li>
 *   <li><b>服主修好文件后必须能读</b>（人工修复路径不能被只读闩永久锁死）。</li>
 * </ol>
 *
 * <p>第 1 条与第 2 条的输入在文件系统上都是「{@code shop.yml} 不存在」，
 * 判据必须是可区分的：本实现用 {@code shop.yml.corrupt} 是否存在作为跨进程信号，
 * 用 {@code YamlFileGate} 的本进程只读闩作为同进程信号。</p>
 */
class ShopConfigQuarantineRebuildTest extends MockBukkitTestBase {

    /** SnakeYAML 必然拒绝的形态（未闭合的 flow sequence）。 */
    private static final String CORRUPT_SHOP_YML = """
            shop:
              items:
                broken: [unclosed
            """;

    /** 服主手写的一份合法配置，刻意与出厂模板的货币不同，便于断言「没被覆盖」。 */
    private static final String ADMIN_SHOP_YML = """
            shop:
              currency:
                material: DIAMOND
                name: "&bCustom Coin"
              npc:
                name: "&eCustom Keeper"
              gui:
                title: "&6Custom Shop"
                size: 27
              items:
                admin_probe:
                  slot: 0
                  price: 42
                  type: MATERIAL
                  icon:
                    material: BOW
            """;

    private BareHost host;
    private ShopConfigLoader loader;
    private File shopFile;
    private File corruptFile;

    @BeforeEach
    void setUp() {
        host = loadBareHost();
        loader = new ShopConfigLoader(host);
        shopFile = new File(host.getDataFolder(), "shop.yml");
        corruptFile = new File(host.getDataFolder(), "shop.yml.corrupt");
    }

    // ================================================================ 回归本体

    @Test
    @DisplayName("F1 回归：坏文件被隔离后，同进程第二次 load() 不得写回出厂模板")
    void secondLoadAfterQuarantineDoesNotRebuildFactoryTemplate() throws IOException {
        TestPaths.write(shopFile, CORRUPT_SHOP_YML);

        assertThrows(IllegalStateException.class, loader::load,
                "首次 load 必须失败并触发隔离（F1 的原意：不得降级成空商店）");
        assertFalse(shopFile.exists(), "坏文件必须已被隔离搬走（shop.yml 不应还在原地）");
        assertTrue(corruptFile.exists(), "隔离产物 shop.yml.corrupt 必须存在");

        // ---- 关键：第二次 load。此时 shop.yml 不存在 —— 与「首次安装」无法从文件系统区分 ----
        assertThrows(IllegalStateException.class, loader::load,
                "隔离后的 shop.yml 不存在，但这是「被搬走」而不是「首次安装」；"
                        + "此处若成功返回，说明 saveResource 写回了出厂模板，"
                        + "服主的商品/价格/货币名/NPC 名/GUI 标题已被出厂值覆盖");

        assertFalse(shopFile.exists(),
                "第二次 load 之后 shop.yml 仍不得被写出来 —— 重建出厂模板正是本回归的核心杀伤");
        assertTrue(corruptFile.exists(),
                "隔离产物必须原样保留，供服主对照修复");
    }

    @Test
    @DisplayName("F1 回归：重启（新 loader 实例）后 .corrupt 仍在时，不得写回出厂模板")
    void restartedLoaderDoesNotRebuildFactoryTemplateWhileCorruptSiblingExists() throws IOException {
        TestPaths.write(shopFile, CORRUPT_SHOP_YML);
        assertThrows(IllegalStateException.class, loader::load);
        assertTrue(corruptFile.exists(), "前置条件：隔离产物存在");

        // 新实例 = 新进程（YamlFileGate 的进程内闩全部重置）。跨重启只能靠磁盘信号判定。
        ShopConfigLoader afterRestart = new ShopConfigLoader(host);

        assertThrows(IllegalStateException.class, afterRestart::load,
                "重启后的首个 load 若成功，就是把出厂模板写回了被隔离的 shop.yml —— "
                        + "评审描述的「坏文件 → 插件禁用 + 文件被搬走 + 下次启动静默写回出厂模板」链条最后一步");

        assertFalse(shopFile.exists(), "重启路径同样不得重建出厂模板");
        assertTrue(corruptFile.exists(), "隔离产物必须保留到服主显式处理");
    }

    // ================================================================ 防「修过头」

    @Test
    @DisplayName("首次安装（无 shop.yml、无 .corrupt）仍必须写出出厂模板并解析成功")
    void firstInstallStillWritesFactoryTemplate() {
        assertFalse(shopFile.exists(), "前置条件：全新数据目录");
        assertFalse(corruptFile.exists(), "前置条件：没有隔离产物");

        ShopConfig config = loader.load();

        assertTrue(shopFile.exists(),
                "首次安装必须生成 shop.yml；否则商店在全新服务器上直接不可用");
        assertFalse(corruptFile.exists(), "正常路径不得凭空产生隔离产物");
        assertEquals(Material.EMERALD, config.getCurrencyMaterial());
        assertEquals(54, config.getGuiSize());
        assertEquals(16, config.getItems().size(),
                "出厂模板共 16 件商品；数量不符说明读到的不是模板："
                        + config.getItems().stream().map(ShopItem::getId).toList());
    }

    @Test
    @DisplayName("服主显式删掉 .corrupt 后重启，允许重置出厂模板（逃生口，不能被保护逻辑堵死）")
    void deletingCorruptSiblingAllowsFactoryResetAfterRestart() throws IOException {
        TestPaths.write(shopFile, CORRUPT_SHOP_YML);
        assertThrows(IllegalStateException.class, loader::load);
        assertTrue(corruptFile.exists());

        // 服主认账：「我就是要一份干净的 shop.yml」。删掉隔离产物 + 重启即是显式同意。
        // 必须用新实例：YamlFileGate 的进程内闩刻意不自动解封（同 ArenaManager 的约定），
        // 所以「删 .corrupt 但不重启」不会立刻放行——这是有意的，见类注释的风险说明。
        assertTrue(corruptFile.delete(), "测试前置：删除隔离产物失败");
        ShopConfigLoader afterRestart = new ShopConfigLoader(host);

        ShopConfig config = afterRestart.load();

        assertTrue(shopFile.exists(), "没有隔离产物时，「文件不存在」重新等于「首次安装」，必须重建");
        assertEquals(16, config.getItems().size(), "重建的必须是完整出厂模板");
    }

    @Test
    @DisplayName("同进程内删掉 .corrupt 但不重启：闸门仍拒绝重建（隔离不得被删文件动作绕过）")
    void deletingCorruptSiblingWithoutRestartStillRefusesRebuild() throws IOException {
        TestPaths.write(shopFile, CORRUPT_SHOP_YML);
        assertThrows(IllegalStateException.class, loader::load);
        assertTrue(corruptFile.delete(), "测试前置：删除隔离产物失败");

        assertThrows(IllegalStateException.class, loader::load,
                "闸门的「ABSENT 不解除锁定」是本回归的最后一道防线：删掉 .corrupt 不能等于同意覆盖");
        assertFalse(shopFile.exists(), "未重启时同样不得写回出厂模板");
    }

    // ================================================================ 人工修复路径

    @Test
    @DisplayName("隔离后服主手写回合法 shop.yml：load() 必须成功，且不得被模板覆盖")
    void adminRepairedFileLoadsAfterQuarantine() throws IOException {
        TestPaths.write(shopFile, CORRUPT_SHOP_YML);
        assertThrows(IllegalStateException.class, loader::load);
        assertTrue(corruptFile.exists(), "前置条件：坏文件已被隔离");

        // 服主从 .corrupt 取回内容、修好后放回 shop.yml（.corrupt 留在原地也无妨）
        TestPaths.write(shopFile, ADMIN_SHOP_YML);

        ShopConfig config = loader.load();

        assertEquals(Material.DIAMOND, config.getCurrencyMaterial(),
                "修好的文件必须被真的读进来，而不是被出厂模板（EMERALD）顶掉");
        assertEquals("&bCustom Coin", config.getCurrencyName(), "currency.name 必须保留");
        assertEquals("&eCustom Keeper", config.getNpcName(), "npc.name 必须保留");
        assertEquals("&6Custom Shop", config.getGuiTitle(), "gui.title 必须保留");
        assertEquals(1, config.getItems().size(),
                "服主自己的商品必须还在；16 件说明读的是出厂模板");
        assertEquals("admin_probe", config.getItems().get(0).getId());
        assertEquals(42, config.getItems().get(0).getPrice());
        assertEquals(ADMIN_SHOP_YML, TestPaths.read(shopFile),
                "load() 是只读路径，不得改写服主刚修好的文件");
    }

    @Test
    @DisplayName("修好后再被改坏：第二次隔离仍然生效，且仍不重建模板")
    void secondQuarantineStillThrowsAndStillDoesNotRebuild() throws IOException {
        TestPaths.write(shopFile, CORRUPT_SHOP_YML);
        assertThrows(IllegalStateException.class, loader::load);

        TestPaths.write(shopFile, ADMIN_SHOP_YML);
        assertEquals(Material.DIAMOND, loader.load().getCurrencyMaterial(),
                "前置条件：修好的文件必须先读成功（同时验证只读闩会被 OK 读盘解开）");

        TestPaths.write(shopFile, CORRUPT_SHOP_YML);
        assertThrows(IllegalStateException.class, loader::load, "再次被改坏必须再次失败");
        assertTrue(corruptFile.exists(), "第二次隔离同样要留下 .corrupt");
        assertFalse(shopFile.exists(), "第二次隔离会把 shop.yml 再次搬走");

        assertThrows(IllegalStateException.class, loader::load,
                "第二次隔离后的 load 同样不得重建模板");
        assertFalse(shopFile.exists(), "第二次隔离后也不得写回出厂模板");
    }

    // ================================================================ 诊断信息

    @Test
    @DisplayName("隔离态下的失败必须点名 shop.yml.corrupt 并给出恢复指引")
    void quarantineFailureMessageNamesTheQuarantineFile() throws IOException {
        TestPaths.write(shopFile, CORRUPT_SHOP_YML);
        assertThrows(IllegalStateException.class, loader::load);

        IllegalStateException failure = assertThrows(IllegalStateException.class, loader::load,
                "隔离态下继续拒绝加载");

        String message = failure.getMessage();
        assertNotNull(message, "失败必须带诊断信息");
        assertTrue(message.contains("shop.yml"), "必须点名文件：" + message);
        assertTrue(message.contains("corrupt"),
                "必须告诉服主现场已被搬到 shop.yml.corrupt，否则他会在数据目录里找不到原始配置：" + message);
    }
}

package com.hilltopvillage.shop;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;

import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import org.bukkit.Material;
import org.bukkit.World;
import org.bukkit.entity.Item;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.PlayerInventory;
import org.bukkit.persistence.PersistentDataContainer;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import com.hilltopvillage.testsupport.BareHost;
import com.hilltopvillage.testsupport.MockBukkitTestBase;
import com.hilltopvillage.util.LanguageManager;

/**
 * F5：{@code shop.purchase-success} 的消息数量必须是「实际买到的数量」，
 * 而不是 {@code addItem} 合并后留在传入 {@code product} 上的余量。
 *
 * <p><b>缺陷机理</b>：{@code ShopListener#purchase} 先把 {@code product} 交给
 * {@code player.getInventory().addItem(product)}，再用 {@code product.getAmount()} 拼消息。
 * Paper 1.21.4 的 {@code CraftInventory#addItem} 在把商品并进已有的半满叠时，会<b>原地修改</b>
 * 调用方传入的 {@code ItemStack}，把它的数量改成没放进去的余量。于是「背包里已有 60 支箭、
 * 买 8 支」这种形态：4 支并进旧叠（60 → 64），4 支溢出，{@code product} 被改成 4，
 * 成功消息就报成 x4 —— 玩家实际到账 8 支（4 支在包里 + 4 支掉在脚下）。</p>
 *
 * <p><b>为什么不用 Mockito / PlayerMock</b>：本用例要钉的是
 * <i>ShopListener 在 addItem 之后读取 product 数量</i> 这个调用顺序缺陷，而不是某个测试框架
 * 是否复刻了 Paper 的原地修改语义。这里用 JDK 动态代理实现 {@code PlayerInventory#addItem}
 * 的桩，精确复刻 Paper 的行为（把传入 stack 的数量改成余量 4，并把余量放进返回的
 * overflow map）；Player / World / Item / PDC 也只实现本流程真正会走到的方法。
 * 这样既不依赖 MockBukkit 的 addItem 实现细节，也不受本机 Mockito inline mock maker
 * 无法 self-attach 的限制。</p>
 *
 * <p><b>红测判据</b>：未修复代码在 addItem 之后读 {@code product.getAmount()} → 捕获到 "4"，
 * 断言期望 "8" 失败；修复后在调用 addItem 之前捕获数量 → 捕获到 "8"，断言通过。</p>
 */
class ShopListenerPurchaseMessageTest extends MockBukkitTestBase {

    /** 出厂 arrow 一次给 8 支；本用例只关心数量语义，价格取 2。 */
    private static final int PURCHASED_AMOUNT = 8;
    /** 模拟「旧叠只能再并进 4 支」后剩下的余量。 */
    private static final int POST_MERGE_REMAINDER = 4;
    private static final int PRICE = 2;

    @Test
    @DisplayName("成功消息报购买量 8，而不是 addItem 合并后的余量 4")
    void successMessageReportsPurchasedAmountNotPostMergeRemainder() {
        BareHost host = loadBareHost();
        ShopItem item = new ShopItem("arrow", 2, PRICE, "MATERIAL",
                PURCHASED_AMOUNT, Material.ARROW, null, List.of(), false);
        ItemStack product = new ItemStack(Material.ARROW, PURCHASED_AMOUNT);

        PlayerInventory bag = proxy(PlayerInventory.class, (proxy, method, args) -> {
            if ("addItem".equals(method.getName())) {
                ItemStack[] passed = (ItemStack[]) args[0];
                assertEquals(1, passed.length, "夹具前提：purchase 每次只投递一个 ItemStack");
                ItemStack stack = passed[0];
                assertEquals(PURCHASED_AMOUNT, stack.getAmount(),
                        "夹具前提：addItem 收到的是完整购买量 " + PURCHASED_AMOUNT);
                // Paper 1.21.4 CraftInventory#addItem 的原地修改：把传入 stack 的数量改成余量，
                // 并把该余量放进 overflow（4 支落地）。这是本用例显式复刻的目标语义。
                stack.setAmount(POST_MERGE_REMAINDER);
                Map<Integer, ItemStack> overflow = new LinkedHashMap<>();
                overflow.put(0, stack);
                return overflow;
            }
            return defaultValue(method.getReturnType());
        });

        PersistentDataContainer pdc = proxy(PersistentDataContainer.class,
                (proxy, method, args) -> defaultValue(method.getReturnType()));
        Item dropped = proxy(Item.class, (proxy, method, args) -> {
            if ("getPersistentDataContainer".equals(method.getName())) return pdc;
            return defaultValue(method.getReturnType());
        });
        World world = proxy(World.class, (proxy, method, args) -> {
            if ("dropItemNaturally".equals(method.getName())) return dropped;
            return defaultValue(method.getReturnType());
        });
        List<String> sentMessages = new ArrayList<>();
        Player player = proxy(Player.class, (proxy, method, args) -> {
            switch (method.getName()) {
                case "getInventory":
                    return bag;
                case "getWorld":
                    return world;
                case "getLocation":
                    // World#dropItemNaturally 的桩忽略坐标，不需要真实 Location。
                    return null;
                case "sendMessage":
                    if (args != null && args.length == 1 && args[0] instanceof String message) {
                        sentMessages.add(message);
                    }
                    return null;
                case "equals":
                    return proxy == args[0];
                case "hashCode":
                    return System.identityHashCode(proxy);
                case "toString":
                    return "F5-test-player";
                default:
                    return defaultValue(method.getReturnType());
            }
        });

        // 捕获 shop.purchase-success 的占位符实参：{0}=商品名、{1}=数量、{2}=价格。
        List<String> capturedAmounts = new ArrayList<>();
        LanguageManager lang = new LanguageManager(host) {
            @Override
            public String getFor(Player p, String key) {
                return "msg";
            }

            @Override
            public String getFor(Player p, String key, Object... args) {
                if ("shop.purchase-success".equals(key) && args != null && args.length >= 3) {
                    capturedAmounts.add(String.valueOf(args[1]));
                }
                return "msg";
            }
        };

        // 只覆盖 purchase 需要的三个协作方法；构造函数仍走真实的 ShopManager 初始化。
        ShopManager shop = new ShopManager(host, lang) {
            @Override
            public int countCurrency(Player p) {
                return 100;
            }

            @Override
            public boolean removeCurrency(Player p, int amount) {
                return true;
            }

            @Override
            public ItemStack deliverItem(ShopItem requested) {
                return product;
            }
        };
        ShopListener listener = new ShopListener(shop, lang);

        invokePurchase(listener, player, item);

        // 夹具自检：addItem 确实原地改写了 product，消息缺陷的触发条件成立。
        assertEquals(POST_MERGE_REMAINDER, product.getAmount(),
                "夹具自检：模拟的 Paper addItem 应把传入 product 改成余量 "
                        + POST_MERGE_REMAINDER + "，否则本用例没有复现缺陷形态");

        assertFalse(capturedAmounts.isEmpty(),
                "购买成功后必须发出 shop.purchase-success 消息（未捕获到说明流程提前返回）");
        assertEquals(List.of(String.valueOf(PURCHASED_AMOUNT)), capturedAmounts,
                "成功消息的数量必须是购买量 " + PURCHASED_AMOUNT + "，而不是 addItem 合并后的余量 "
                        + POST_MERGE_REMAINDER + "。实际捕获：" + capturedAmounts
                        + "（未修复代码在 addItem 之后读 product.getAmount()，会得到余量）");
        assertFalse(sentMessages.isEmpty(), "成功消息应通过 player.sendMessage 发出");
    }

    /** 走真实的 {@code ShopListener#purchase}（private，方法签名在修复前后不变）。 */
    private static void invokePurchase(ShopListener listener, Player player, ShopItem item) {
        try {
            Method purchase = ShopListener.class.getDeclaredMethod(
                    "purchase", Player.class, ShopItem.class);
            purchase.setAccessible(true);
            purchase.invoke(listener, player, item);
        } catch (ReflectiveOperationException failure) {
            throw new AssertionError("无法调用 ShopListener#purchase："
                    + failure.getClass().getSimpleName() + " " + failure.getMessage(), failure);
        }
    }

    @SuppressWarnings("unchecked")
    private static <T> T proxy(Class<T> type, InvocationHandler handler) {
        return (T) Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, handler);
    }

    private static Object defaultValue(Class<?> type) {
        if (!type.isPrimitive() || type == void.class) return null;
        if (type == boolean.class) return false;
        if (type == byte.class) return (byte) 0;
        if (type == short.class) return (short) 0;
        if (type == char.class) return (char) 0;
        if (type == int.class) return 0;
        if (type == long.class) return 0L;
        if (type == float.class) return 0f;
        if (type == double.class) return 0d;
        return null;
    }
}

package com.hilltopvillage.shop;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.ArrayList;
import java.util.List;

import org.bukkit.Location;
import org.bukkit.Material;
import org.bukkit.World;
import org.bukkit.entity.Item;
import org.bukkit.event.entity.ItemMergeEvent;
import org.bukkit.event.inventory.ClickType;
import org.bukkit.event.inventory.InventoryAction;
import org.bukkit.event.inventory.InventoryClickEvent;
import org.bukkit.event.inventory.InventoryType;
import org.bukkit.inventory.Inventory;
import org.bukkit.inventory.InventoryView;
import org.bukkit.inventory.ItemStack;
import org.bukkit.persistence.PersistentDataType;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;
import org.mockbukkit.mockbukkit.entity.PlayerMock;

import com.hilltopvillage.HilltopVillagePlugin;
import com.hilltopvillage.arena.ArenaInstance;
import com.hilltopvillage.testsupport.BareHost;
import com.hilltopvillage.testsupport.MockBukkitTestBase;
import com.hilltopvillage.util.LanguageManager;

/**
 * {@code F5-droploss} 的回归网：<b>{@link ShopListener#PAID_DROP_KEY} 必须活过原版并物</b>。
 *
 * <p><b>缺陷原文</b>：{@code ShopListener} 把 {@code PAID_DROP_KEY} 打在 <b>Item 实体</b>的
 * PDC 上（{@code ShopListener.java:159}、{@code :197}）。原版
 * {@code net.minecraft.world.entity.item.ItemEntity#merge} 在合并时从 <b>{@code this}</b>
 * 的栈 {@code copyWithCount} 重建结果，并把 <b>{@code other}</b> 的实体
 * {@code discard(EntityRemoveEvent.Cause.MERGE)}。因此：</p>
 *
 * <ul>
 *   <li>{@code this} 是付过钱的那件 → key 在它自己身上，存活，安全；</li>
 *   <li>{@code this} 是<b>普通</b>那件、付过钱的是 {@code other} → 存活实体没有 key，
 *       付过钱的那件连同它的实体 PDC 一起被 discard → 下次
 *       {@code ArenaInstance.clearDroppedItems()} 把货当垃圾删掉。</li>
 * </ul>
 *
 * <p>哪一方是 {@code this} 取决于同一 tick 内谁先 {@code tick()}，所以这不是罕见竞态，
 * 而是「竞技场商店附近只要有一件同材质普通掉落物就有一半概率」的常态缺陷。</p>
 *
 * <p><b>修复方式</b>：监听 {@link ItemMergeEvent}，在看到合并<b>确实未被取消</b>后，
 * 把 key 预先转移到<b>存活</b>的那个实体（{@link ItemMergeEvent#getTarget()}）上。
 * 事件是全流程唯一的合并闸门（{@code CraftEventFactory.callItemMergeEvent}），
 * 且在主线程、合并执行之前同步触发，因此这一步能可靠地改写存活实体的 PDC。</p>
 *
 * <p><b>本类钉住的三件事</b>：</p>
 * <ol>
 *   <li>{@link MergeSurvival}：带 key + 普通同种 → 合并后存活实体仍被判定为「已付对价」，
 *       且两个合并方向（key 在 entity / key 在 target）都成立；</li>
 *   <li>{@link NoOverclean}：<b>防修过头</b> —— 两件普通掉落物合并后，
 *       存活实体<b>不得</b>被标成已付款，否则 {@code clearDroppedItems} 会永久留它，
 *       竞技场越来越脏；</li>
 *   <li>{@link PickupStillWorks}：合并后的货仍能被玩家捡到（`pickupDelay` 不得被改成永久）。</li>
 * </ol>
 *
 * <p><b>MockBukkit 的能力边界（如实说明）</b>：MockBukkit <b>没有</b>原版
 * {@code ItemEntity#merge} 的实现，{@code ItemMock} 也不参与 tick 合并。因此本类
 * <b>不能</b>做「让两件掉落物真的合并」的端到端验证。这里验证的是
 * <b>{@link ShopListener} 对 {@link ItemMergeEvent} 的响应</b>——即我们自己的判定与打标逻辑——
 * 事件参数与真实 Paper 的实参映射已按
 * {@code CraftEventFactory.callItemMergeEvent} 字节码核对（见报告 0.5）。
 * 也就是说：<b>本类证明「若原版按已知语义触发该事件，标记会活下来」，
 * 不证明「原版一定按该语义触发」</b>。后者只能靠真实服务器验证（见报告第 4 节）。</p>
 */
class ShopPaidDropMergeTest extends MockBukkitTestBase {

    /** 41 = 36 主背包 + 4 护甲 + 1 副手；{@code addItem} 会用到全部 41 个槽位。 */
    private static final int MOCK_INVENTORY_SLOTS = 41;

    // ================================================================ 夹具

    private static InventoryView view(PlayerMock viewer, Inventory top, Inventory bottom) {
        InventoryView view = mock(InventoryView.class);
        when(view.getTopInventory()).thenReturn(top);
        when(view.getBottomInventory()).thenReturn(bottom);
        when(view.getPlayer()).thenReturn(viewer);
        when(view.getType()).thenReturn(InventoryType.CHEST);
        when(view.getInventory(org.mockito.ArgumentMatchers.anyInt())).thenAnswer(invocation -> {
            int raw = invocation.getArgument(0);
            if (raw < 0) return null;
            return raw < top.getSize() ? top : bottom;
        });
        when(view.convertSlot(org.mockito.ArgumentMatchers.anyInt())).thenAnswer(invocation -> {
            int raw = invocation.getArgument(0);
            return raw < top.getSize() ? raw : raw - top.getSize();
        });
        return view;
    }

    private static LanguageManager stubLanguage() {
        return mock(LanguageManager.class, invocation -> {
            if (invocation.getMethod().getReturnType() == String.class) return "msg";
            return org.mockito.Answers.RETURNS_DEFAULTS.answer(invocation);
        });
    }

    private static ShopItem factoryItem(ShopManager shop, String id) {
        return shop.getShopConfig().getItems().stream()
                .filter(item -> item.getId().equals(id))
                .findFirst()
                .orElseThrow(() -> new AssertionError("出厂 shop.yml 里应有商品 " + id));
    }

    private static void fillEverySlot(PlayerMock player) {
        for (int i = 0; i < MOCK_INVENTORY_SLOTS; i++) {
            player.getInventory().setItem(i, new ItemStack(Material.DIRT, 64));
        }
    }

    /** 「已付对价」的判据必须与 {@code ArenaInstance.clearDroppedItems} 完全一致。 */
    private static boolean isPaidDrop(Item item) {
        // 标记在 Item **实体**的 PDC 上（与 ArenaInstance.clearDroppedItems 的口径一致）。
        return item.getPersistentDataContainer()
                .has(ShopListener.PAID_DROP_KEY, PersistentDataType.BYTE);
    }

    /** 写入侧：与生产实现 {@code ShopListener#markPaidDrop} 同一容器（实体 PDC）。 */
    private static void markPaid(Item item) {
        item.getPersistentDataContainer()
                .set(ShopListener.PAID_DROP_KEY, PersistentDataType.BYTE, (byte) 1);
    }

    private static List<String> describeDrops(World world) {
        List<String> out = new ArrayList<>();
        for (Item item : world.getEntitiesByClass(Item.class)) {
            out.add(item.getItemStack().getType() + "x" + item.getItemStack().getAmount()
                    + (isPaidDrop(item) ? "[PAID]" : "[plain]"));
        }
        return out;
    }

    // ================================================================ 核心：标记活过合并

    /**
     * <b>核心用例</b>：带 key 的掉落物与普通同种掉落物合并，存活实体仍被识别为「已付对价」。
     *
     * <p>两个方向都必须成立，因为哪一方是「存活者」由原版 tick 顺序决定：</p>
     * <ul>
     *   <li>方向 A：付过钱的是 {@code event.getEntity()}（将被 discard）→ 必须补标到 target；</li>
     *   <li>方向 B：付过钱的是 {@code event.getTarget()}（存活者）→ key 天然保留，不得被清掉。</li>
     * </ul>
     *
     * <p>方向 A 是当前实现真正会丢货的那一半；方向 B 是「别把已经对的改坏」的守卫。</p>
     */
    @Nested
    @DisplayName("核心 —— 合并后存活实体仍被判定为已付对价")
    class MergeSurvival {

        private BareHost host;
        private ShopManager shop;
        private ShopListener listener;
        private LanguageManager lang;
        private World world;

        @BeforeEach
        void setUp() {
            host = loadBareHost();
            lang = stubLanguage();
            shop = new ShopManager(host, lang);
            shop.reload();
            // 真实注册：Node A 依赖 @EventHandler 真的被 Bukkit 分发器找到。
            // 直接调方法只能证明「方法体对」，证明不了「注解/事件类型接得上」。
            listener = MockBukkit_loadRegisteredListener();
            world = server.addSimpleWorld("merge-test-world");
        }

        /** 用 MockBukkit 加载一个真正注册了 {@link ShopListener} 的插件宿主。 */
        private ShopListener MockBukkit_loadRegisteredListener() {
            ShopListener fresh = new ShopListener(shop, lang);
            org.bukkit.Bukkit.getPluginManager().registerEvents(fresh, host);
            return fresh;
        }

        private Item dropAt(Material material, boolean paid) {
            Item item = world.dropItemNaturally(new Location(world, 0.5, 64, 0.5),
                    new ItemStack(material, 1));
            if (paid) {
                markPaid(item);
            }
            return item;
        }

        @Test
        @DisplayName("方向 A：付过钱的那件是 getEntity()（将被 discard）→ 合并后存活者必须带 key")
        void paidDropAsRemovedSideKeepsKeyOnSurvivor() {
            Item paid = dropAt(Material.BOW, true);
            Item plain = dropAt(Material.BOW, false);
            assertTrue(isPaidDrop(paid), "前置条件：paid 应带 key");
            assertFalse(isPaidDrop(plain), "前置条件：plain 不应带 key");

            // 真实实参映射：CraftEventFactory.callItemMergeEvent(other, this)，
            // 故 getEntity() == other（被 discard），getTarget() == this（存活）。
            // 这里构造「付过钱的是 other」= 当前实现会丢 key 的那一半。
            org.bukkit.Bukkit.getPluginManager().callEvent(new ItemMergeEvent(paid, plain));

            assertTrue(isPaidDrop(plain),
                    "F5-droploss：付过钱的掉落物作为被合并方（other / getEntity）消失时，"
                            + "key 必须转移到存活实体上。否则 ArenaInstance.clearDroppedItems 会把"
                            + "玩家付过钱的货当普通掉落物删掉 —— 这就是「付了钱拿不到货」本身。"
                            + "当前存活实体：" + describeDrops(world));
        }

        @Test
        @DisplayName("方向 B：付过钱的就是存活者（getTarget）→ key 不得被清掉")
        void paidDropAsSurvivingSideKeepsKey() {
            Item paid = dropAt(Material.BOW, true);
            Item plain = dropAt(Material.BOW, false);

            // 付过钱的是 this（getTarget / 存活），普通的是 other（getEntity / 被 discard）
            org.bukkit.Bukkit.getPluginManager().callEvent(new ItemMergeEvent(plain, paid));

            assertTrue(isPaidDrop(paid),
                    "守卫半：付过钱的本来就是存活方，key 天然保留；任何实现都不许把它清掉。"
                            + "当前存活实体：" + describeDrops(world));
        }

        @Test
        @DisplayName("修复后：竞技场重置不会删掉合并后的那件货（两半接得上）")
        void survivorOfMergeSurvivesArenaReset() {
            // 这条用真实竞技场世界：只有把「合并后仍带 key」与「clearDroppedItems 跳过」串起来，
            // 才能证明修复对玩家真的有效，而不只是「PDC 里有个字节」。
            HilltopVillagePlugin plugin = loadFullPluginWithArenas();
            ArenaInstance arena = plugin.getMultiArenaManager().getArena("arena1");
            assertNotNull(arena, "arena1 未被启用 —— 夹具失效");
            World arenaWorld = arena.getGameManager().getGameWorld();
            assertNotNull(arenaWorld, "arena1 的 GameManager 没有世界");

            Location at = new Location(arenaWorld, 0.5, 64, 0.5);
            Item paid = arenaWorld.dropItemNaturally(at, new ItemStack(Material.BOW, 1));
            markPaid(paid);
            Item plain = arenaWorld.dropItemNaturally(at, new ItemStack(Material.BOW, 1));

            ShopListener registered = new ShopListener(plugin.getShopManager(), lang);
            org.bukkit.Bukkit.getPluginManager().registerEvents(registered, plugin);

            // 模拟原版：付过钱的那件被合并掉，存活的是普通那件
            org.bukkit.Bukkit.getPluginManager().callEvent(new ItemMergeEvent(paid, plain));
            plain.setItemStack(new ItemStack(Material.BOW, 2));
            paid.remove();

            arena.resetNow();

            List<Item> remaining = new ArrayList<>(arenaWorld.getEntitiesByClass(Item.class));
            assertEquals(1, remaining.size(),
                    "F5-droploss：合并后的那件是玩家花水晶买的货，重置后必须还在。实际："
                            + describeDrops(arenaWorld));
            assertEquals(Material.BOW, remaining.get(0).getItemStack().getType(),
                    "活下来的必须是那件 BOW，实际：" + describeDrops(arenaWorld));
            assertTrue(isPaidDrop(remaining.get(0)),
                    "活下来的那件必须仍被识别为已付对价，实际：" + describeDrops(arenaWorld));
        }
    }

    // ================================================================ 防修过头

    /**
     * <b>防修过头</b>：两件<b>都不带</b> key 的普通掉落物合并，存活实体不得被标成已付款。
     *
     * <p>若实现写成「只要收到 ItemMergeEvent 就给 target 打标」，普通物品会获得永生，
     * {@code clearDroppedItems} 从此再也清不掉它们 —— 修复退化成新的实体泄漏。
     * 这一组就是判据 2。</p>
     */
    @Nested
    @DisplayName("防修过头 —— 普通掉落物合并后仍不带 key（清理必须继续有效）")
    class NoOverclean {

        private BareHost host;
        private ShopManager shop;
        private ShopListener listener;
        private LanguageManager lang;
        private World world;

        @BeforeEach
        void setUp() {
            host = loadBareHost();
            lang = stubLanguage();
            shop = new ShopManager(host, lang);
            shop.reload();
            listener = new ShopListener(shop, lang);
            org.bukkit.Bukkit.getPluginManager().registerEvents(listener, host);
            world = server.addSimpleWorld("no-overclean-world");
        }

        @Test
        @DisplayName("普通 + 普通 合并：存活实体不带 key")
        void plainMergeDoesNotInheritKey() {
            Item a = world.dropItemNaturally(new Location(world, 0.5, 64, 0.5),
                    new ItemStack(Material.STONE, 1));
            Item b = world.dropItemNaturally(new Location(world, 0.5, 64, 0.5),
                    new ItemStack(Material.STONE, 1));
            assertFalse(isPaidDrop(a) || isPaidDrop(b), "前置条件：两件都不应带 key");

            org.bukkit.Bukkit.getPluginManager().callEvent(new ItemMergeEvent(a, b));

            assertFalse(isPaidDrop(b),
                    "判据 2（防修过头）：两件普通掉落物合并后，存活实体绝不能变成「已付对价」，"
                            + "否则它会被 clearDroppedItems 永久放行，竞技场世界里的垃圾实体只增不减。"
                            + "实际：" + describeDrops(world));
        }

        @Test
        @DisplayName("竞技场：合并后的普通掉落物仍被 clearDroppedItems 删除（清理没被改坏）")
        void plainMergeStillGetsCleanedUp() {
            HilltopVillagePlugin plugin = loadFullPluginWithArenas();
            ArenaInstance arena = plugin.getMultiArenaManager().getArena("arena1");
            assertNotNull(arena, "arena1 未被启用 —— 夹具失效");
            World arenaWorld = arena.getGameManager().getGameWorld();
            assertNotNull(arenaWorld, "arena1 的 GameManager 没有世界");

            Location at = new Location(arenaWorld, 0.5, 64, 0.5);
            Item a = arenaWorld.dropItemNaturally(at, new ItemStack(Material.STONE, 1));
            Item b = arenaWorld.dropItemNaturally(at, new ItemStack(Material.STONE, 1));

            ShopListener registered = new ShopListener(plugin.getShopManager(), lang);
            org.bukkit.Bukkit.getPluginManager().registerEvents(registered, plugin);

            org.bukkit.Bukkit.getPluginManager().callEvent(new ItemMergeEvent(a, b));
            b.setItemStack(new ItemStack(Material.STONE, 2));
            a.remove();

            arena.resetNow();

            assertTrue(arenaWorld.getEntitiesByClass(Item.class).isEmpty(),
                    "判据 2：普通掉落物合并后仍必须被竞技场重置清理。若这里不为空，说明「修复」"
                            + "把 patch 变成了「谁都不删」。实际：" + describeDrops(arenaWorld));
        }
    }

    // ================================================================ 基本功能 + 可捡

    /**
     * <b>基本功能</b>：购买后背包满 → 掉落物带标记 → 清理时被跳过；且合并后<b>仍能被捡起</b>。
     *
     * <p>第二条是方案 (a) 的反例钉子：若有人日后改成「用极长 pickupDelay 阻止合并」，
     * {@code playerTouch} 会在 {@code pickupDelay != 0} 时直接 return（见报告 0.4 字节码），
     * 玩家就再也捡不到货，那等于用另一种方式违反判据 1。</p>
     */
    @Nested
    @DisplayName("基本功能 —— 购买溢出打标 + 合并后仍可捡")
    class PickupStillWorks {

        private LanguageManager lang;

        @BeforeEach
        void setUp() {
            lang = stubLanguage();
            // 刻意不在这里 addPlayer：ShopManager#reload 会遍历 Bukkit.getOnlinePlayers()
            // 并解引用 p.getOpenInventory().getTopInventory()，而 MockBukkit 对「从未打开过
            // 背包的玩家」返回的 view 里 topInventory 是 null → NPE（ShopManager.java:60）。
            // 买家在用例内部、插件启动之后再创建，绕开这个 MockBukkit 的假世界差异。
        }

        @Test
        @DisplayName("购买溢出 → 掉落物带 key → 竞技场重置跳过它")
        void purchaseOverflowIsMarkedAndSurvivesReset() {
            HilltopVillagePlugin plugin = loadFullPluginWithArenas();
            ArenaInstance arena = plugin.getMultiArenaManager().getArena("arena1");
            assertNotNull(arena, "arena1 未被启用 —— 夹具失效");
            World arenaWorld = arena.getGameManager().getGameWorld();
            assertNotNull(arenaWorld, "arena1 的 GameManager 没有世界");

            // 全量插件已启用，此刻才建买家：ShopManager#reload 在 onEnable 期内执行，
            // 那时若有在线玩家且其 view 的 topInventory 为 null 会 NPE（见 setUp 注释）。
            PlayerMock buyer = server.addPlayer("OverflowBuyer");
            buyer.setLocation(new Location(arenaWorld, 0.5, 64, 0.5));
            assertEquals("hilltop_arena1", buyer.getWorld().getName(),
                    "前置条件：买家必须站在竞技场世界里");

            ShopManager realShop = plugin.getShopManager();
            LanguageManager realLang = plugin.getLanguageManager();
            ShopItem bow = factoryItem(realShop, "bow");
            fillEverySlot(buyer);
            buyer.getInventory().setItem(35, realShop.createCurrencyItem(bow.getPrice() + 1));

            ShopListener realListener = new ShopListener(realShop, realLang);
            ShopGUI gui = new ShopGUI(buyer, realShop, realLang);
            gui.open();
            realListener.onInventoryClick(new InventoryClickEvent(
                    view(buyer, gui.getInventory(), buyer.getInventory()),
                    InventoryType.SlotType.CONTAINER, bow.getSlot(), ClickType.LEFT,
                    InventoryAction.PICKUP_ALL));

            List<Item> drops = new ArrayList<>(arenaWorld.getEntitiesByClass(Item.class));
            assertEquals(1, drops.size(),
                    "前置条件：背包全满买 1 件应恰好掉落 1 件，实际：" + describeDrops(arenaWorld));
            Item dropped = drops.get(0);
            assertTrue(isPaidDrop(dropped),
                    "打标侧：溢出掉落物必须带 PAID_DROP_KEY，实际：" + describeDrops(arenaWorld));

            arena.resetNow();

            List<Item> after = new ArrayList<>(arenaWorld.getEntitiesByClass(Item.class));
            assertEquals(1, after.size(),
                    "跳过侧：带 key 的货必须扛过竞技场重置，实际：" + describeDrops(arenaWorld));
            assertTrue(isPaidDrop(after.get(0)), "重置不得清掉标记");
        }

        @Test
        @DisplayName("合并后的货仍可被玩家捡起（pickupDelay 不得被改成永久）")
        void mergedPaidDropRemainsPickable() {
            BareHost host = loadBareHost();
            ShopListener registered = new ShopListener(new ShopManager(host, lang), lang);
            org.bukkit.Bukkit.getPluginManager().registerEvents(registered, host);

            World world = server.addSimpleWorld("pickup-world");
            Item paid = world.dropItemNaturally(new Location(world, 0.5, 64, 0.5),
                    new ItemStack(Material.BOW, 1));
            markPaid(paid);
            Item plain = world.dropItemNaturally(new Location(world, 0.5, 64, 0.5),
                    new ItemStack(Material.BOW, 1));

            org.bukkit.Bukkit.getPluginManager().callEvent(new ItemMergeEvent(paid, plain));

            assertTrue(isPaidDrop(plain),
                    "方向 A 的最小复现：合并后存活者必须带 key，实际：" + describeDrops(world));
            assertTrue(plain.getPickupDelay() < 32767,
                    "判据 1：合并后的货必须仍能被玩家捡起。若 pickupDelay == 32767，"
                            + "playerTouch 会在 pickupDelay != 0 时直接 return（原版字节码），"
                            + "玩家永远捡不到 —— 那是用「阻止合并」换「拿不到货」，等于没修。"
                            + "实际 pickupDelay=" + plain.getPickupDelay());
        }
    }
}
